/* 安装合并：把旧视图容器移入伞形容器并变成 subview + 插页签栏 */
function installViewMerge(){
  if(window.__viewMergeInstalled) return;
  window.__viewMergeInstalled=true;
  var content=document.getElementById('content');
  if(!content||!document.getElementById('view-alerts')) return;
  /* 1. 新建四个伞形容器 */
  ['reports','country','datapool','datagov'].forEach(function(u){
    if(!document.getElementById('view-'+u)){
      var el=document.createElement('div');
      el.className='view'; el.id='view-'+u;
      content.appendChild(el);
    }
  });
  /* 2. 既有伞形（alerts/settings）：原内容包一层 subview */
  ['alerts','settings'].forEach(function(u){
    var host=document.getElementById('view-'+u);
    if(!host||document.getElementById('sv-'+u)) return;
    var wrap=document.createElement('div');
    wrap.className='subview active'; wrap.id='sv-'+u;
    while(host.firstChild) wrap.appendChild(host.firstChild);
    host.appendChild(wrap);
  });
  /* 3. 旧视图容器移入伞形，class view→subview */
  Object.keys(VIEW_MERGE_ALIAS).forEach(function(child){
    var u=VIEW_MERGE_ALIAS[child];
    var el=document.getElementById('view-'+child);
    var host=document.getElementById('view-'+u);
    if(!el||!host||el===host) return;
    el.classList.remove('view'); el.classList.add('subview');
    host.appendChild(el);
  });
  /* 4. 页签栏插到每个伞形最前 */
  Object.keys(VIEW_MERGE_TABS).forEach(function(u){
    var host=document.getElementById('view-'+u);
    if(!host||document.getElementById('mtabs-'+u)) return;
    var bar=document.createElement('div');
    bar.className='dc-tabs'; bar.id='mtabs-'+u; bar.style.marginBottom='12px';
    VIEW_MERGE_TABS[u].forEach(function(t,i){
      var d=document.createElement('div');
      d.className='dc-tab'+(i===0?' active':'');
      d.textContent=t.label;
      d.onclick=function(){ navigateTo(t.k); };
      bar.appendChild(d);
    });
    host.insertBefore(bar,host.firstChild);
  });
  /* 5. 默认只显示每个伞形的第一个 subview */
  Object.keys(VIEW_MERGE_TABS).forEach(function(u){
    var tabs=VIEW_MERGE_TABS[u];
    tabs.forEach(function(t,i){
      var el=document.getElementById(t.k===u?('sv-'+u):('view-'+t.k));
      if(el) el.classList.toggle('active',i===0);
    });
  });
}
/* 页签切换：激活 subview + 运行对应视图的 init */
function switchViewTab(u,t){
  var tabs=VIEW_MERGE_TABS[u]; if(!tabs) return false;
  /* 未命中页签（如直接进伞形键）：回落到第一个页签 */
  var has=tabs.some(function(x){return x.k===t;});
  if(!has) t=tabs[0].k;
  tabs.forEach(function(x){
    var el=document.getElementById(x.k===u?('sv-'+u):('view-'+x.k));
    if(!el) return;
    if(x.k===t){ el.classList.add('active'); } else { el.classList.remove('active'); }
  });
  var bar=document.getElementById('mtabs-'+u);
  if(bar){ Array.prototype.forEach.call(bar.children,function(c,i){ c.classList.toggle('active',!!(tabs[i]&&tabs[i].k===t)); }); }
  /* 数据源浮层：仅数据源库页签显示 */
  try{ if(typeof DATASOURCES!=='undefined'){ if(u==='datapool'&&t==='datasources'){ DATASOURCES.init(); } else { DATASOURCES.hide(); } } }catch(e){}
  return true;
}
/* 各视图初始化钩子（从旧 navigateTo 抽出，按最终视图键调用） */
function runViewInit(v){
  setTimeout(function(){
    try{
      if(v==='situation'){ if(SITUATION._needsRefresh){SITUATION._needsRefresh=false;} SITUATION.init(); }
      else if(v==='workbench'){ if(typeof WORKBENCH!=='undefined')WORKBENCH.init(); }
      else if(v==='threatroom'){ if(typeof THREATROOM!=='undefined')THREATROOM.init(); }
      else if(v==='myfocus'){ if(typeof MYFOCUS!=='undefined')MYFOCUS.init(); }
      else if(v==='intel'){ INTELCENTER.init(); }
      else if(v==='monitor'){ MONITOR.init(); }
      else if(v==='assets'){ ASSETS.init(); }
      else if(v==='alerts'){ AVIEW.init(); }
      else if(v==='cosri'){ if(typeof COSRI_VIEW!=='undefined')COSRI_VIEW.init(); }
      else if(v==='countryfile'){ if(typeof COUNTRYFILE!=='undefined')COUNTRYFILE.init(); }
      else if(v==='matrix'){ RISK_FUSION.fuse(); if(typeof MATRIX!=='undefined')MATRIX.init(); }
      else if(v==='forecast'){ FORECAST.init(); }
      else if(v==='datacenter'){ DATACENTER.init(); }
      else if(v==='sidepool'){ if(typeof SIDEPOOL!=='undefined')SIDEPOOL.init(); }
      else if(v==='funnel'){ if(typeof FUNNEL_VIEW!=='undefined')FUNNEL_VIEW.init(); }
      else if(v==='archive'){ if(typeof ARCHIVE_VIEW!=='undefined')ARCHIVE_VIEW.init(); }
      else if(v==='anomaly'){ if(typeof ANOMALY_VIEW!=='undefined')ANOMALY_VIEW.init(); }
      else if(v==='settings'){ SETTINGS.init(); }
      else if(v==='threatorgs'){ if(typeof THREATS!=='undefined')THREATS.render(); }
      else if(v==='autoalert'){ if(typeof AUTOALERT!=='undefined')AUTOALERT.init(); }
      else if(v==='aireport'){ if(typeof AIREPORT!=='undefined')AIREPORT.init(); }
      else if(v==='datasources'){ if(typeof DATASOURCES!=='undefined')DATASOURCES.init(); }
      else if(v==='wechat'){ if(typeof WECHAT!=='undefined')WECHAT.init(); }
      else if(v==='command'){ if(typeof COMMAND!=='undefined'){ if(!COMMAND._incidents)COMMAND.init(); else COMMAND.render(); } }
      else if(v==='analysis'){ if(typeof DATACENTER!=='undefined')DATACENTER.renderAnalysis(false,'analysis-body'); }
      else if(v==='explain'){ if(typeof EXPLAINABILITY!=='undefined')EXPLAINABILITY.render(); }
      else if(v==='role'){ if(typeof ROLE_UI!=='undefined')ROLE_UI.render(); }
    }catch(e){ console.error('runViewInit('+v+')错误:',e); }
  },0);
}
installViewMerge();
document.addEventListener('DOMContentLoaded',installViewMerge);

/* ============================================================
 * COSRI_VIEW — 国别风险画像（2026-08-28 中海安对标 + 国别档案落地）
 * 数据源：/api/cosri（50 国 × 4 维政治/经济/社会/公共安全研究底数）
 * 功能：四维排名榜 + 4 维榜切换 + 单国画像（4 维条形 + 项目 + 30 天事件 + 行动指引）
 * ============================================================ */
const COSRI_VIEW={
  _data:null, _dim:'overall', _selected:null, _initing:false,
  _colors:{'political':'#ff3d7f','economic':'#ffcc00','social':'#00d4ff','security':'#ff3355','overall':'#00ff9f'},
  init(){
    if(this._initing) return;
    this._initing=true;
    var self=this;
    var host=document.getElementById('cosri-content');
    if(!host) return;
    host.innerHTML=
      '<div class="card"><div class="card-tt"><span class="ic">🌐</span>COSRI 国别风险画像 · 中国海外安全研究四维底数</div>'+
      '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center">'+
        '<span style="font-size:12px;color:var(--text2)">排序维度：</span>'+
        '<span class="dc-tab'+(this._dim==='overall'?' active':'')+'" data-dim="overall" style="cursor:pointer">综合</span>'+
        '<span class="dc-tab'+(this._dim==='security'?' active':'')+'" data-dim="security" style="cursor:pointer">🛡️ 公共安全</span>'+
        '<span class="dc-tab'+(this._dim==='political'?' active':'')+'" data-dim="political" style="cursor:pointer">🏛️ 政治</span>'+
        '<span class="dc-tab'+(this._dim==='economic'?' active':'')+'" data-dim="economic" style="cursor:pointer">💰 经济</span>'+
        '<span class="dc-tab'+(this._dim==='social'?' active':'')+'" data-dim="social" style="cursor:pointer">👥 社会</span>'+
        '<span style="margin-left:auto;font-size:11px;color:var(--text3)">口径：2025 研判底数 · 50 国 · 综合=四维均值</span>'+
      '</div>'+
      '<div id="cosri-rank"></div>'+
      '<div id="cosri-detail"></div></div>';
    Array.prototype.forEach.call(host.querySelectorAll('.dc-tab[data-dim]'), function(b){
      b.addEventListener('click', function(){
        self._dim=b.getAttribute('data-dim');
        self._render();
      });
    });
    this._load();
  },
  _load(){
    var self=this;
    fetch('/api/cosri').then(function(r){return r.json();}).then(function(d){
      self._data=d; self._render();
    }).catch(function(e){
      var host=document.getElementById('cosri-rank');
      if(host) host.innerHTML='<div style="padding:24px;text-align:center;color:var(--orange)">加载 COSRI 失败：'+e.message+'</div>';
    });
  },
  _bar(val,max){var w=Math.min(100,(val/max)*100);return '<div style="flex:1;height:8px;background:var(--bg2);border-radius:4px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:linear-gradient(90deg,#00d4ff,#00ff9f)"></div></div>';},
  _render(){
    if(!this._data) return;
    var self=this;
    var list=this._data.countries.slice().sort(function(a,b){return b[this._dim]-a[this._dim];}.bind(this));
    var host=document.getElementById('cosri-rank');
    /* 顶级前 10 醒目 + 全部可点击展开 */
    var top=list.slice(0,10);
    var rest=list.slice(10);
    var colorOf=this._dim==='overall'?'#00ff9f':(this._colors[this._dim]||'#00d4ff');
    function row(c, i){
      var v=c[self._dim];
      var tierBadge=c.tier==='TIER1'?'<span class="badge b-red" style="font-size:9px;margin-left:4px">TIER1</span>':c.tier==='TIER2'?'<span class="badge b-orange" style="font-size:9px;margin-left:4px">TIER2</span>':c.tier==='TIER3'?'<span class="badge b-blue" style="font-size:9px;margin-left:4px">TIER3</span>':'';
      return '<tr data-cn="'+c.country+'" style="cursor:pointer;border-bottom:1px solid var(--border)" onclick="COSRI_VIEW.select(\''+c.country.replace(/'/g,"\\'")+'\')">'+
        '<td style="padding:6px 8px;color:var(--text3);font-size:11px;width:30px">'+(i+1)+'</td>'+
        '<td style="padding:6px 8px"><b style="color:var(--text1)">'+c.country+'</b>'+tierBadge+(c.projectCount?' <span style="font-size:10px;color:var(--cyan)">· '+c.projectCount+'项目</span>':'')+'</td>'+
        '<td style="padding:6px 4px;width:60%;min-width:200px"><div style="display:flex;align-items:center;gap:8px">'+self._bar(v,10)+'<span style="font-size:12px;font-weight:700;color:'+colorOf+';width:30px;text-align:right">'+v+'</span></div></td>'+
        '<td style="padding:6px 8px;font-size:10px;color:var(--text3)">政'+c.political+' 经'+c.economic+' 社'+c.social+' 安'+c.security+'</td>'+
      '</tr>';
    }
    var html='<div class="table-wrap" style="max-height:380px;overflow-y:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--bg2)"><th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">#</th><th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">国家</th><th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">风险分</th><th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">四维明细</th></tr></thead><tbody>';
    html+=top.map(function(c,i){return row(c,i);}).join('');
    if(rest.length){ html+='<tr><td colspan="4" style="padding:4px 8px;background:var(--bg2);font-size:10px;color:var(--text3);text-align:center">以下 '+rest.length+' 国 风险较低 ▼ 点击展开</td></tr>'; html+=rest.map(function(c,i){return row(c,i+10);}).join(''); }
    html+='</tbody></table></div>';
    host.innerHTML=html;
    /* 保留已选 */
    if(this._selected) this._renderDetail();
  },
  select(cn){
    this._selected=cn;
    Array.prototype.forEach.call(document.querySelectorAll('#cosri-rank tr[data-cn]'), function(tr){
      tr.style.background=tr.getAttribute('data-cn')===cn?'rgba(0,212,255,0.08)':'';
    });
    this._renderDetail();
  },
  _renderDetail(){
    var cn=this._selected;
    var host=document.getElementById('cosri-detail');
    if(!cn||!host){ if(host) host.innerHTML=''; return; }
    host.innerHTML='<div style="margin-top:14px;padding:12px;background:var(--bg2);border-radius:8px;text-align:center;color:var(--text2)">正在加载 '+cn+' 画像…</div>';
    var self=this;
    fetch('/api/cosri/'+encodeURIComponent(cn)).then(function(r){return r.json();}).then(function(d){
      if(d.error){ host.innerHTML='<div style="padding:14px;color:var(--orange)">'+d.error+'</div>'; return; }
      var dimBars=['political','economic','social','security'].map(function(k){
        var v=d.scores[k], name=d.dimNames[k], color=self._colors[k];
        return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px"><span style="width:80px;font-size:12px;color:var(--text2)">'+name+'</span>'+self._bar(v,10)+'<span style="font-size:13px;font-weight:700;color:'+color+';width:30px;text-align:right">'+v+'</span></div>';
      }).join('');
      var tierBadge=d.tier==='TIER1'?'<span class="badge b-red" style="margin-left:8px">TIER1 重点</span>':d.tier==='TIER2'?'<span class="badge b-orange" style="margin-left:8px">TIER2 关注</span>':d.tier==='TIER3'?'<span class="badge b-blue" style="margin-left:8px">TIER3 一般</span>':'';
      var projs=d.projects.length?d.projects.map(function(p){return '<span class="badge" style="background:rgba(0,212,255,0.15);color:var(--cyan);margin:2px">'+p.name+' <span style="opacity:0.6;font-size:9px">('+p.cat+')</span></span>';}).join(''):'<span style="color:var(--text3)">无中资项目</span>';
      var events=d.recentEvents.length?d.recentEvents.slice(0,8).map(function(e){
        var t=new Date(e.time).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
        return '<div style="padding:6px 10px;border-bottom:1px solid var(--border);display:flex;gap:10px;align-items:center"><span style="font-size:10px;color:var(--text3);min-width:90px">'+t+'</span><span style="font-size:11px;color:var(--orange);min-width:60px">'+e.type+'</span><span style="flex:1;font-size:12px">'+(e.title||'').slice(0,80)+'</span></div>';
      }).join(''):'<div style="padding:12px;color:var(--text3);text-align:center">近 30 天暂无入库事件</div>';
      var guide=d.guide.map(function(g){return '<div style="padding:6px 10px;background:rgba(255,204,0,0.08);border-left:3px solid var(--orange);margin-bottom:4px;border-radius:0 6px 6px 0;font-size:12px;line-height:1.6">'+g+'</div>';}).join('');
      host.innerHTML=
        '<div class="card" style="margin-top:14px;border:1px solid var(--cyan);box-shadow:0 0 20px rgba(0,212,255,0.1)"><div class="card-tt"><span class="ic">🎯</span>'+cn+' 国别画像 '+tierBadge+
          '<span style="margin-left:auto;font-size:11px;color:var(--text3)">综合 '+d.overall+' · '+d.asOf+'</span></div>'+
        '<div class="grid" style="grid-template-columns:1fr 1fr;gap:14px">'+
          '<div><div class="card-tt"><span class="ic">📊</span>COSRI 四维评分</div>'+dimBars+
            '<div style="margin-top:10px;padding:8px;background:var(--bg3);border-radius:6px;font-size:11px;color:var(--text2)">综合 = ('+d.scores.political+'+'+d.scores.economic+'+'+d.scores.social+'+'+d.scores.security+') / 4 = '+d.overall+'</div></div>'+
          '<div><div class="card-tt"><span class="ic">🏗️</span>中资项目暴露 ('+d.projects.length+')</div><div style="display:flex;flex-wrap:wrap">'+projs+'</div>'+
            '<div class="card-tt mt-12"><span class="ic">🎯</span>行动指引 ('+d.guide.length+')</div>'+guide+'</div>'+
        '</div>'+
        '<div class="card-tt mt-12"><span class="ic">📅</span>近 30 天入库事件 ('+d.recentCount+')</div>'+events+
        '</div>';
    });
  }
};

/* ============================================================
 * COUNTRYFILE — 国家档案总表（COSRI 对标 P1，2026-08-29）
 * 70+国总表：综合风险值 / 近7d预警数 / 关键项目数 / 关键人员数 /
 * 24h趋势sparkline / 风险等级；过滤：风险等级 / 有中资项目 / 地区；
 * 点行 → COUNTRY_DRAWER 联动侧抽屉。
 * 数据：COUNTRIES + ALERTS 实时统计 + ENTERPRISES 项目/人员 + /api/cosri 四维。
 * ============================================================ */
const COUNTRYFILE={
  _cosri:null,_loaded:false,_fRisk:'all',_fProj:false,_fRegion:'all',_sort:'risk',
  init(){
    var self=this;
    var host=document.getElementById('countryfile-content');
    if(!host)return;
    host.innerHTML=
      '<div class="card"><div class="card-tt"><span class="ic">📊</span>国家档案总表 · 风险值×预警×项目×人员 一表通览'+
        '<span style="margin-left:auto;font-size:10px;color:var(--text3);font-weight:400">点任意行 → 国别联动详情抽屉</span></div>'+
      '<div id="cf-stats" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px"></div>'+
      '<div style="display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap;align-items:center">'+
        '<span style="font-size:11px;color:var(--text2)">过滤：</span>'+
        '<select id="cf-f-risk" style="background:var(--bg2);color:var(--text1);border:1px solid var(--border);border-radius:6px;padding:4px 8px;font-size:11px">'+
          '<option value="all">全部风险等级</option><option value="critical">极高(≥8)</option><option value="high">高(6-8)</option><option value="elevated">中高(4-6)</option><option value="moderate">中低(<4)</option></select>'+
        '<select id="cf-f-region" style="background:var(--bg2);color:var(--text1);border:1px solid var(--border);border-radius:6px;padding:4px 8px;font-size:11px"><option value="all">全部地区</option></select>'+
        '<span id="cf-f-proj" style="cursor:pointer;padding:4px 10px;border:1px solid var(--border);border-radius:6px;font-size:11px;color:var(--text3);user-select:none">🏗️ 仅看有中资项目</span>'+
        '<span style="margin-left:auto;font-size:11px;color:var(--text2)">排序：</span>'+
        '<span class="dc-tab" id="cf-s-risk" style="cursor:pointer">风险值</span>'+
        '<span class="dc-tab" id="cf-s-alert" style="cursor:pointer">7日预警</span>'+
        '<span style="font-size:10px;color:var(--text3)">🔄 <span id="cf-refresh" style="cursor:pointer;color:var(--cyan)">刷新</span></span>'+
      '</div>'+
      '<div id="cf-table"></div></div>';
    document.getElementById('cf-f-risk').onchange=function(){self._fRisk=this.value;self._render();};
    document.getElementById('cf-f-region').onchange=function(){self._fRegion=this.value;self._render();};
    document.getElementById('cf-f-proj').onclick=function(){self._fProj=!self._fProj;this.style.borderColor=self._fProj?'var(--cyan)':'';this.style.color=self._fProj?'var(--cyan)':'var(--text3)';this.style.background=self._fProj?'rgba(0,212,255,0.08)':'';self._render();};
    document.getElementById('cf-s-risk').onclick=function(){self._sort='risk';self._render();};
    document.getElementById('cf-s-alert').onclick=function(){self._sort='alert';self._render();};
    document.getElementById('cf-refresh').onclick=function(){self._loaded=false;self._load();};
    if(!this._loaded)this._load(); else this._render();
  },
  _load(){
    var self=this;
    fetch('/api/cosri').then(function(r){return r.ok?r.json():null;}).then(function(d){
      self._cosri=d;self._loaded=true;self._render();
    }).catch(function(){self._loaded=true;self._render();});
  },
  /* 行数据构建：COUNTRIES ∪ ALERTS 出现国 ∪ COSRI 国 */
  _rows(){
    var cosriMap={};
    (this._cosri&&this._cosri.countries||[]).forEach(function(c){cosriMap[c.country]=c;});
    /* 每国统计：7d/24h 预警 + ENTERPRISES 项目/人员 */
    var st={};
    function bucket(n){
      if(!st[n])st[n]={a7:0,a24:0,proj:0,pers:0,ents:0,inv:0};
      return st[n];
    }
    var now=Date.now();
    (ALERTS||[]).forEach(function(a){
      var n=a.country;if(!n)return;
      var t=null;try{t=new Date(String(a.time||'').replace(' ','T')).getTime();}catch(e){}
      if(!t||isNaN(t))return;
      var ageH=(now-t)/3600000;
      var b=bucket(n);
      if(ageH<=24*7)b.a7++;
      if(ageH<=24)b.a24++;
    });
    (ENTERPRISES||[]).forEach(function(e){
      (e.countries||[]).forEach(function(cn){var b=bucket(cn);b.ents++;b.pers+=(e.personnel||0);b.inv+=(e.investment||0);});
      (e.projects||[]).forEach(function(p){if(p.c){bucket(p.c).proj++;}});
    });
    var seen={},rows=[];
    COUNTRIES.forEach(function(c){
      seen[c.name]=true;
      var s=st[c.name]||{a7:0,a24:0,proj:0,pers:0,ents:0,inv:0};
      var cs=cosriMap[c.name];
      rows.push({name:c.name,flag:c.flag,region:c.region,risk:calcOverall(c.scores),
        a7:s.a7,a24:s.a24,proj:Math.max(s.proj,(cs&&cs.projectCount)||0),pers:s.pers,
        tier:cs?cs.tier:null,hasLon:true});
    });
    /* ALERTS 中出现但未建档的国家 */
    Object.keys(st).forEach(function(n){
      if(seen[n])return;
      seen[n]=true;
      var cs=cosriMap[n];
      var s=st[n];
      rows.push({name:n,flag:'🌐',region:cs?(cs.region||'其他'):'其他',
        risk:cs?cs.overall:null,a7:s.a7,a24:s.a24,proj:Math.max(s.proj,(cs&&cs.projectCount)||0),
        pers:s.pers,tier:cs?cs.tier:null,hasLon:false});
    });
    return rows;
  },
  _spark(series,w,h,color){
    if(typeof COUNTRY_DRAWER!=='undefined'&&COUNTRY_DRAWER._spark)return COUNTRY_DRAWER._spark(series,w,h,color);
    return '';
  },
  _render(){
    var self=this;
    var host=document.getElementById('cf-table');
    if(!host)return;
    var rows=this._rows();
    /* 统计卡 */
    var stEl=document.getElementById('cf-stats');
    if(stEl){
      var hi=rows.filter(function(r){return r.risk!==null&&r.risk>=8;}).length;
      var withProj=rows.filter(function(r){return r.proj>0;}).length;
      var a7all=rows.reduce(function(s,r){return s+r.a7;},0);
      var t1=rows.filter(function(r){return r.tier==='TIER1';}).length;
      stEl.innerHTML=
        '<div class="stat-card" style="flex:1;min-width:120px"><div class="stat-v" style="color:var(--cyan)">'+rows.length+'</div><div class="stat-l">在档国家</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:120px"><div class="stat-v" style="color:var(--red)">'+hi+'</div><div class="stat-l">极高风险国</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:120px"><div class="stat-v" style="color:var(--orange)">'+t1+'</div><div class="stat-l">TIER1 重点国</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:120px"><div class="stat-v" style="color:var(--green)">'+withProj+'</div><div class="stat-l">有中资项目国</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:120px"><div class="stat-v">'+a7all+'</div><div class="stat-l">近7日预警总量</div></div>';
    }
    /* 地区下拉（一次性填充） */
    var regSel=document.getElementById('cf-f-region');
    if(regSel&&regSel.options.length<=1){
      var regions=[...new Set(rows.map(function(r){return r.region;}))].sort();
      regions.forEach(function(rg){
        var o=document.createElement('option');o.value=rg;o.textContent=rg;regSel.appendChild(o);
      });
    }
    /* 过滤 */
    rows=rows.filter(function(r){
      if(self._fRegion!=='all'&&r.region!==self._fRegion)return false;
      if(self._fProj&&!(r.proj>0))return false;
      if(self._fRisk!=='all'){
        if(r.risk===null)return false;
        if(self._fRisk==='critical'&&r.risk<8)return false;
        if(self._fRisk==='high'&&(r.risk<6||r.risk>=8))return false;
        if(self._fRisk==='elevated'&&(r.risk<4||r.risk>=6))return false;
        if(self._fRisk==='moderate'&&r.risk>=4)return false;
      }
      return true;
    });
    /* 排序 */
    rows.sort(function(a,b){
      if(self._sort==='alert')return (b.a7-a.a7)||((b.risk||0)-(a.risk||0));
      return ((b.risk===null?-1:b.risk)-(a.risk===null?-1:a.risk))||(b.a7-a.a7);
    });
    /* 表格 */
    var lvOf=function(r){
      if(r.risk===null)return {label:'未评估',color:'var(--text3)',cls:'b-blue'};
      return getLevel(r.risk);
    };
    var html='<div class="table-wrap" style="max-height:640px;overflow-y:auto"><table style="width:100%;border-collapse:collapse;min-width:760px"><thead><tr style="background:var(--bg2);position:sticky;top:0;z-index:2">'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">国家</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2);width:110px">综合风险值</th>'+
      '<th style="text-align:right;padding:8px;font-size:11px;color:var(--text2);width:80px">近7d预警</th>'+
      '<th style="text-align:right;padding:8px;font-size:11px;color:var(--text2);width:80px">关键项目</th>'+
      '<th style="text-align:right;padding:8px;font-size:11px;color:var(--text2);width:90px">在外人员</th>'+
      '<th style="text-align:center;padding:8px;font-size:11px;color:var(--text2);width:120px">24h/7d 趋势</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2);width:90px">风险等级</th></tr></thead><tbody>';
    if(!rows.length){
      html+='<tr><td colspan="7" style="padding:30px;text-align:center;color:var(--text3)">当前过滤条件下无国家，试试放宽过滤</td></tr>';
    }
    rows.forEach(function(r){
      var lv=lvOf(r);
      var tierB=r.tier==='TIER1'?'<span class="badge b-red" style="font-size:8px;padding:0 3px;margin-left:4px">T1</span>':r.tier==='TIER2'?'<span class="badge b-orange" style="font-size:8px;padding:0 3px;margin-left:4px">T2</span>':'';
      var riskCell=r.risk===null?'<span style="color:var(--text3)">—</span>':'<b style="color:'+lv.color+';font-size:13px;font-family:\'Courier New\',monospace">'+r.risk.toFixed(1)+'</b>';
      var a7Cell=r.a7>0?'<b style="color:'+(r.a7>=10?'var(--red)':r.a7>=4?'var(--orange)':'var(--cyan)')+'">'+r.a7+'</b>':'<span style="color:var(--text3)">0</span>';
      var projCell=r.proj>0?'<b style="color:var(--cyan)">'+r.proj+'</b>':'<span style="color:var(--text3)">—</span>';
      var persCell=r.pers>0?r.pers.toLocaleString():'<span style="color:var(--text3)">—</span>';
      /* 7 日 sparkline（懒计算：只有该国有预警才画） */
      var spark='';
      if(r.a7>0){
        try{spark=COUNTRY_DRAWER._spark(COUNTRY_DRAWER._dailyCounts(r.name,7),96,26,lv.color==='var(--text3)'?'#00d4ff':lv.color);}catch(e){}
      }
      var esc=r.name.replace(/'/g,"\\'");
      html+='<tr data-cn="'+r.name+'" onclick="COUNTRY_DRAWER.open(\''+esc+'\')" style="cursor:pointer;border-bottom:1px solid var(--border);transition:.12s" onmouseover="this.style.background=\'rgba(0,212,255,0.05)\'" onmouseout="this.style.background=\'\'">'+
        '<td style="padding:7px 8px"><span style="margin-right:6px">'+r.flag+'</span><b style="color:var(--text1);font-size:12px">'+r.name+'</b>'+tierB+'<div style="font-size:9px;color:var(--text3);margin-top:1px">'+r.region+'</div></td>'+
        '<td style="padding:7px 8px">'+riskCell+'</td>'+
        '<td style="padding:7px 8px;text-align:right">'+a7Cell+(r.a24>0?'<div style="font-size:9px;color:var(--red)">24h +'+r.a24+'</div>':'')+'</td>'+
        '<td style="padding:7px 8px;text-align:right">'+projCell+'</td>'+
        '<td style="padding:7px 8px;text-align:right">'+persCell+'</td>'+
        '<td style="padding:4px 8px;text-align:center">'+(spark||'<span style="color:var(--text3);font-size:10px">—</span>')+'</td>'+
        '<td style="padding:7px 8px"><span class="badge '+lv.cls+'" style="font-size:9px">'+lv.label+'</span></td></tr>';
    });
    html+='</tbody></table></div>';
    host.innerHTML=html;
  }
};

/* ============================================================
 * ANOMALY_VIEW — 异动信号（2026-08-28 服务端三件之一）
 * 数据源：/api/anomaly/signals（类别×国家 7 日基线 vs 今日，超阈值=升温/突发）
 * 优质信号已由服务端写入预警中心共享库（ANOM- 前缀）
 * ============================================================ */
const ANOMALY_VIEW={
  _data:null, _sel:-1,
  init(){
    var self=this;
    var host=document.getElementById('anomaly-content');
    if(!host) return;
    host.innerHTML=
      '<div class="card"><div class="card-tt"><span class="ic">📈</span>风险异动信号 · 类别×国家基线环比监测</div>'+
      '<div id="anomaly-stats" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px"></div>'+
      '<div style="display:flex;gap:8px;margin-bottom:10px;align-items:center;flex-wrap:wrap">'+
        '<span class="dc-tab" id="anomaly-refresh" style="cursor:pointer">🔄 立即检测</span>'+
        '<span id="anomaly-meta" style="font-size:11px;color:var(--text3)">加载中…</span></div>'+
      '<div id="anomaly-list"></div><div id="anomaly-detail"></div></div>';
    document.getElementById('anomaly-refresh').onclick=function(){ self._load(true); };
    this._load(false);
  },
  _load(force){
    var self=this;
    var el=document.getElementById('anomaly-meta');
    if(el) el.textContent=force?'正在检测（基线比对中）…':'加载中…';
    fetch('/api/anomaly/'+(force?'detect':'signals')).then(function(r){return r.json();}).then(function(d){
      self._data=d; self._sel=-1; self._render();
    }).catch(function(e){
      var host=document.getElementById('anomaly-list');
      if(host) host.innerHTML='<div style="padding:24px;text-align:center;color:var(--orange)">异动检测失败：'+e.message+'</div>';
    });
  },
  _bar(ratio){
    var w=Math.min(100,(ratio/5)*100);
    var c=ratio>=3?'#ff3355':ratio>=1.8?'#ffcc00':'#00d4ff';
    return '<div style="flex:1;height:8px;background:var(--bg2);border-radius:4px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:'+c+'"></div></div>';
  },
  _lvlBadge(l){
    if(l==='red') return '<span class="badge b-red">红</span>';
    if(l==='orange') return '<span class="badge b-orange">橙</span>';
    return '<span class="badge b-yellow">黄</span>';
  },
  _render(){
    if(!this._data) return;
    var self=this, d=this._data;
    var meta=document.getElementById('anomaly-meta');
    if(meta) meta.textContent='最近检测：'+(d.at?new Date(d.at).toLocaleString('zh-CN'):'—')+' · 扫描 '+((d.scanned||0))+' 个方向';
    var st=document.getElementById('anomaly-stats');
    if(st){
      var maxR=0; (d.signals||[]).forEach(function(s){ if((s.ratio||0)>maxR)maxR=s.ratio; });
      st.innerHTML=
        '<div class="stat-card" style="flex:1;min-width:140px"><div class="stat-v" style="color:var(--cyan)">'+(d.signals||[]).length+'</div><div class="stat-l">触发异动信号</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:140px"><div class="stat-v">'+(d.scanned||0)+'</div><div class="stat-l">监测方向（类别×国家）</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:140px"><div class="stat-v" style="color:'+(maxR>=3?'#ff3355':'#ffcc00')+'">'+(maxR?maxR+' 倍':'—')+'</div><div class="stat-l">最高环比倍数</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:140px"><div class="stat-v" style="color:var(--green)">'+(d.pushed||0)+'</div><div class="stat-l">已推送预警中心</div></div>';
    }
    var list=document.getElementById('anomaly-list');
    var sigs=d.signals||[];
    if(!sigs.length){
      list.innerHTML='<div style="padding:28px;text-align:center;color:var(--text3)">当前各方向情报量均在 7 日基线正常区间内，暂无异动信号<div style="font-size:11px;margin-top:6px">判定口径：有效基线（7 天总量≥3）今日≥4 条且≥日均 1.8 倍=升温；无基线今日≥6 条=突发</div></div>';
      var det=document.getElementById('anomaly-detail'); if(det) det.innerHTML='';
      return;
    }
    var html='<div class="table-wrap" style="max-height:420px;overflow-y:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--bg2)">'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">#</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">国家/方向</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">今日/7日均</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">环比倍数</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">等级</th>'+
      '<th style="text-align:left;padding:8px;font-size:11px;color:var(--text2)">状态</th></tr></thead><tbody>';
    sigs.forEach(function(s,i){
      var tierBadge=s.tier==='TIER1'?' <span class="badge b-red" style="font-size:9px">TIER1</span>':s.tier==='TIER2'?' <span class="badge b-orange" style="font-size:9px">TIER2</span>':'';
      var inAlert=s.inAlert?'<span style="color:var(--green);font-size:11px">已进预警中心</span>':'<span style="color:var(--text3);font-size:11px">仅监测'+((s.interestScore!=null)?'（关联分 '+s.interestScore+'）':'')+'</span>';
      html+='<tr data-i="'+i+'" style="cursor:pointer;border-bottom:1px solid var(--border)">'+
        '<td style="padding:6px 8px;color:var(--text3);font-size:11px;width:28px">'+(i+1)+'</td>'+
        '<td style="padding:6px 8px"><b style="color:var(--text1)">'+s.country+'</b>'+tierBadge+'<span style="font-size:10px;color:var(--text3)"> · '+s.typeLabel+'</span></td>'+
        '<td style="padding:6px 8px;font-size:12px"><b style="color:'+(s.today>=8?'#ff3355':'var(--orange)')+'">'+s.today+'</b><span style="color:var(--text3)"> / '+(s.avg||0)+'</span></td>'+
        '<td style="padding:6px 4px;width:28%;min-width:140px"><div style="display:flex;align-items:center;gap:8px">'+self._bar(s.ratio||0)+'<span style="font-size:12px;font-weight:700;width:52px;text-align:right;color:'+(s.ratio>=3?'#ff3355':s.ratio>=1.8?'#ffcc00':'var(--cyan)')+'">'+(s.ratio?s.ratio+'倍':'突发')+'</span></div></td>'+
        '<td style="padding:6px 8px">'+self._lvlBadge(s.level)+'</td>'+
        '<td style="padding:6px 8px">'+inAlert+'</td></tr>';
    });
    html+='</tbody></table></div>';
    list.innerHTML=html;
    Array.prototype.forEach.call(list.querySelectorAll('tr[data-i]'),function(tr){
      tr.onclick=function(){ self.select(parseInt(tr.getAttribute('data-i'),10)); };
    });
    if(this._sel>=0&&sigs[this._sel]) this._renderDetail();
  },
  select(i){
    this._sel=i;
    Array.prototype.forEach.call(document.querySelectorAll('#anomaly-list tr[data-i]'),function(tr){
      tr.style.background=parseInt(tr.getAttribute('data-i'),10)===i?'rgba(0,212,255,0.08)':'';
    });
    this._renderDetail();
  },
  _renderDetail(){
    var s=(this._data&&this._data.signals||[])[this._sel];
    var host=document.getElementById('anomaly-detail');
    if(!s||!host){ if(host) host.innerHTML=''; return; }
    var samples=(s.samples||[]).map(function(t){
      return '<div style="padding:5px 10px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text2)">· '+t+'</div>';
    }).join('')||'<div style="padding:10px;color:var(--text3)">无样例</div>';
    host.innerHTML=
      '<div class="card" style="margin-top:14px;border:1px solid var(--cyan);box-shadow:0 0 20px rgba(0,212,255,0.1)"><div class="card-tt"><span class="ic">🎯</span>'+s.country+' · '+s.typeLabel+' 异动详情 '+this._lvlBadge(s.level)+
      '<span style="margin-left:auto;font-size:11px;color:var(--text3)">赋分 '+s.risk_score+'</span></div>'+
      '<div class="grid" style="grid-template-columns:1fr 1fr;gap:14px">'+
        '<div>'+
          '<div style="display:flex;gap:16px;margin-bottom:10px;flex-wrap:wrap">'+
            '<div><div style="font-size:10px;color:var(--text3)">今日入库</div><div style="font-size:22px;font-weight:700;color:'+(s.today>=8?'#ff3355':'var(--orange)')+'">'+s.today+' 条</div></div>'+
            '<div><div style="font-size:10px;color:var(--text3)">7 日日均</div><div style="font-size:22px;font-weight:700;color:var(--cyan)">'+(s.avg||0)+' 条</div></div>'+
            '<div><div style="font-size:10px;color:var(--text3)">环比倍数</div><div style="font-size:22px;font-weight:700;color:'+(s.ratio>=3?'#ff3355':s.ratio>=1.8?'#ffcc00':'var(--cyan)')+'">'+(s.ratio?s.ratio+' 倍':'突发（无基线）')+'</div></div>'+
          '</div>'+
          '<div style="padding:8px 10px;background:rgba(255,204,0,0.08);border-left:3px solid var(--orange);border-radius:0 6px 6px 0;font-size:12px;line-height:1.7;color:var(--text2)">'+
            (s.kind==='升温'?'该方向今日情报量达 7 日均值的 '+s.ratio+' 倍，超出异动阈值（1.8 倍），风险呈升温态势。':'近 7 天无基线记录，今日集中入库 '+s.today+' 条，属突发聚集，需核实是否单源刷量或事件爆发。')+
            (s.alert&&s.alert.risk_rationale?'<br>'+s.alert.risk_rationale:'')+
          '</div>'+
          (s.alert?'<div style="margin-top:8px;padding:8px 10px;background:rgba(0,255,159,0.06);border-left:3px solid var(--green);border-radius:0 6px 6px 0;font-size:12px;color:var(--text2)">处置建议：'+s.alert.zone_action+'</div>':'')+
        '</div>'+
        '<div><div class="card-tt"><span class="ic">📰</span>今日样例标题（真实入库数据）</div><div style="max-height:200px;overflow-y:auto">'+samples+'</div></div>'+
      '</div></div>';
  }
};

/* ============================================================
 * FUNNEL_VIEW — 采集漏斗（2026-08-28 服务端三件之二）
 * 数据源：/api/funnel/today（拦截→入库→预警，全链路真实口径，每级可点开明细）
 * ============================================================ */
const FUNNEL_VIEW={
  _data:null, _open:{},
  init(){
    var self=this;
    var host=document.getElementById('funnel-content');
    if(!host) return;
    host.innerHTML='<div class="card"><div class="card-tt"><span class="ic">🔻</span>采集漏斗 · 拦截 → 入库 → 预警 全链路</div>'+
      '<div id="funnel-meta" style="font-size:11px;color:var(--text3);margin-bottom:12px">加载中…</div>'+
      '<div id="funnel-stages"></div></div>';
    this._load();
  },
  _load(){
    var self=this;
    fetch('/api/funnel/today').then(function(r){return r.json();}).then(function(d){
      self._data=d; self._render();
    }).catch(function(e){
      var host=document.getElementById('funnel-stages');
      if(host) host.innerHTML='<div style="padding:24px;text-align:center;color:var(--orange)">漏斗加载失败：'+e.message+'</div>';
    });
  },
  _render(){
    if(!this._data) return;
    var self=this, d=this._data;
    var meta=document.getElementById('funnel-meta');
    if(meta) meta.textContent=d.date+' 口径 · 生成于 '+new Date(d.generatedAt).toLocaleTimeString('zh-CN')+' · 点击各级展开明细';
    var host=document.getElementById('funnel-stages');
    if(!host) return;
    var max=1; d.stages.forEach(function(s){ if(s.count>max)max=s.count; });
    var colors={blocked:'#ff3355',stored:'#00d4ff',alerts:'#00ff9f'};
    var html='';
    d.stages.forEach(function(s){
      var w=Math.max(6,Math.round((s.count/max)*100));
      var c=colors[s.key]||'#00d4ff';
      var open=!!self._open[s.key];
      html+=
      '<div style="margin-bottom:10px">'+
        '<div onclick="FUNNEL_VIEW.toggle(\''+s.key+'\')" style="cursor:pointer;display:flex;align-items:center;gap:12px;padding:10px 12px;background:var(--bg2);border-radius:8px;border:1px solid var(--border)">'+
          '<span style="font-size:13px;font-weight:700;color:var(--text1);min-width:72px">'+s.name+'</span>'+
          '<div style="flex:1;height:26px;background:var(--bg3);border-radius:13px;overflow:hidden;position:relative">'+
            '<div style="width:'+w+'%;height:100%;background:linear-gradient(90deg,'+c+'33,'+c+');transition:width .4s"></div>'+
            '<span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);font-size:14px;font-weight:700;color:#fff">'+s.count+' 条</span>'+
          '</div>'+
          '<span style="font-size:11px;color:var(--text3)">'+(open?'▲ 收起':'▼ 明细')+'</span>'+
        '</div>';
      if(open) html+=self._detail(s);
      html+='</div>';
    });
    /* 转化率（真实口径：入库/(入库+今日拦截池)，预警/入库） */
    var blocked=0,stored=0,alerts=0,pool=0;
    d.stages.forEach(function(s){ if(s.key==='blocked'){blocked=s.count;pool=s.poolToday||0;} if(s.key==='stored')stored=s.count; if(s.key==='alerts')alerts=s.count; });
    var inRate=stored+pool>0?Math.round(stored/(stored+pool)*100):null;
    var alRate=stored>0?Math.round(alerts/stored*100):null;
    /* 预警由 _serverAlertGen 每3分钟回看 24h 数据生成（含昨日剩余），跨日时段会出现预警量>入库量，
     * 显示时附带"含昨日回看"说明，避免领导误判数据质量。 */
    var alRateNote = alRate!=null && alRate > 100 ? ' 含昨日回看（24h 窗口）' : '';
    html+='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:6px">'+
      (inRate!=null?'<div style="padding:8px 14px;background:var(--bg2);border-radius:8px;font-size:12px;color:var(--text2)">今日通过率（入库/(入库+数据池拦截)）：<b style="color:var(--cyan)">'+inRate+'%</b></div>':'')+
      (alRate!=null?'<div style="padding:8px 14px;background:var(--bg2);border-radius:8px;font-size:12px;color:var(--text2)">预警转化率（预警/入库）：<b style="color:var(--green)">'+alRate+'%</b>'+alRateNote+'</div>':'')+
      '<div style="padding:8px 14px;background:var(--bg2);border-radius:8px;font-size:11px;color:var(--text3)">拦截口径：数据池今日（持久化）+ 入库闸审计（重启以来·内存，含重复/旧闻等不落池拦截）</div>'+
    '</div>';
    host.innerHTML=html;
  },
  toggle(k){ this._open[k]=!this._open[k]; this._render(); },
  _kvTable(obj,limit){
    var ks=Object.keys(obj||{}).sort(function(a,b){return obj[b]-obj[a];}).slice(0,limit||12);
    if(!ks.length) return '<div style="padding:8px;color:var(--text3);font-size:11px">无记录</div>';
    var max=obj[ks[0]]||1;
    return ks.map(function(k){
      var w=Math.round(obj[k]/max*100);
      return '<div style="display:flex;align-items:center;gap:8px;padding:3px 0">'+
        '<span style="font-size:11px;color:var(--text2);min-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+k+'</span>'+
        '<div style="flex:1;height:10px;background:var(--bg3);border-radius:5px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:var(--cyan)"></div></div>'+
        '<span style="font-size:11px;color:var(--text1);font-weight:700;min-width:32px;text-align:right">'+obj[k]+'</span></div>';
    }).join('');
  },
  _rowsTable(rows){
    if(!rows||!rows.length) return '<div style="padding:8px;color:var(--text3);font-size:11px">无记录</div>';
    var max=rows[0].c||1;
    return rows.map(function(r){
      var w=Math.round(r.c/max*100);
      return '<div style="display:flex;align-items:center;gap:8px;padding:3px 0">'+
        '<span style="font-size:11px;color:var(--text2);min-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+r.k+'</span>'+
        '<div style="flex:1;height:10px;background:var(--bg3);border-radius:5px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:var(--cyan)"></div></div>'+
        '<span style="font-size:11px;color:var(--text1);font-weight:700;min-width:32px;text-align:right">'+r.c+'</span></div>';
    }).join('');
  },
  _detail(s){
    if(s.key==='blocked'){
      var poolSamp=Object.keys(s.samples||{}).map(function(k){
        return '<div style="margin-bottom:6px"><div style="font-size:11px;color:var(--orange);margin-bottom:2px">'+k+' · 样例</div>'+
          (s.samples[k]||[]).map(function(t){return '<div style="font-size:11px;color:var(--text3);padding:1px 0 1px 10px">· '+String(t).slice(0,60)+'</div>';}).join('')+'</div>';
      }).join('');
      return '<div style="padding:12px;background:var(--bg2);border-radius:0 0 8px 8px;border:1px solid var(--border);border-top:none;margin-bottom:10px">'+
        '<div class="grid" style="grid-template-columns:1fr 1fr;gap:14px">'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">🚧</span>数据池拦截分布（今日·持久化）</div>'+this._kvTable(s.detail)+
          '<div style="font-size:10px;color:var(--text3);margin-top:6px">合计 '+s.poolToday+' 条 · 详情见「非预警数据池」页签</div></div>'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">🛡️</span>入库闸审计（重启以来·内存）</div>'+this._kvTable(s.gateDetail,14)+
          '<div style="font-size:10px;color:var(--text3);margin-top:6px">含重复/旧闻/黑名单等不落池拦截 · 服务重启后从零累计</div>'+
          (poolSamp?'<div style="max-height:120px;overflow-y:auto;margin-top:8px">'+poolSamp+'</div>':'')+
        '</div></div></div>';
    }
    if(s.key==='stored'){
      return '<div style="padding:12px;background:var(--bg2);border-radius:0 0 8px 8px;border:1px solid var(--border);border-top:none;margin-bottom:10px">'+
        '<div class="grid" style="grid-template-columns:1fr 1fr;gap:14px">'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">📦</span>按情报类别</div>'+this._rowsTable(s.byType)+'</div>'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">🛰️</span>按采集通道（_sourceType）</div>'+this._rowsTable(s.byChannel)+'</div>'+
        '</div></div>';
    }
    if(s.key==='alerts'){
      return '<div style="padding:12px;background:var(--bg2);border-radius:0 0 8px 8px;border:1px solid var(--border);border-top:none;margin-bottom:10px">'+
        '<div class="grid" style="grid-template-columns:1fr 1fr;gap:14px">'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">🚨</span>按预警等级</div>'+this._kvTable(s.byLevel)+'</div>'+
        '<div><div class="card-tt" style="font-size:12px"><span class="ic">📈</span>异动信号与生成拦截</div>'+
          '<div style="padding:4px 0"><span style="font-size:22px;font-weight:700;color:var(--orange)">'+(s.anomaly||0)+'</span><span style="font-size:11px;color:var(--text3)"> 条异动信号预警（ANOM- 前缀）</span></div>'+
          '<div class="card-tt" style="font-size:11px;margin-top:6px"><span class="ic">🚫</span>预警生成被拒（重启以来·内存）</div>'+this._kvTable(s.gateRejections,10)+
          '<div style="font-size:10px;color:var(--text3);margin-top:4px">已入库但未达预警生成标准（国内/低利益关联/俄乌无关联等）</div></div>'+
        '</div></div>';
    }
    return '';
  }
};

/* ============================================================
 * ARCHIVE_VIEW — 归档检索（2026-08-28 服务端三件之三）
 * 数据源：/api/archive/search（intel_archive 滚动归档：活跃库仅留 7 天，更早可查不丢）
 * ============================================================ */
const ARCHIVE_VIEW={
  _data:null, _page:1, _q:'', _country:'', _type:'', _since:'', _until:'',
  init(){
    var self=this;
    var host=document.getElementById('archive-content');
    if(!host) return;
    var typeOpts=['','terror_events','security_events','military_conflicts','political_events','natural_disasters','public_health','sanctions_data','social_unrest','infrastructure','geopolitical_intel','economic_risk','legal_compliance','cyber_security'].map(function(t){
      var n={terror_events:'恐怖事件',security_events:'安全事件',military_conflicts:'武装冲突',political_events:'政治事件',natural_disasters:'自然灾害',public_health:'公共卫生',sanctions_data:'制裁措施',social_unrest:'社会动荡',infrastructure:'基础设施',geopolitical_intel:'地缘情报',economic_risk:'经济风险',legal_compliance:'法律合规',cyber_security:'网络安全'}[t];
      return '<option value="'+t+'"'+(self._type===t?' selected':'')+'>'+(t?(n||t):'全类别')+'</option>';
    }).join('');
    host.innerHTML=
      '<div class="card"><div class="card-tt"><span class="ic">📚</span>归档库检索 · 滚动归档（活跃库仅留 7 天，更早数据可查不丢）</div>'+
      '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px">'+
        '<input id="ar-q" placeholder="关键词（标题，中英皆可）" value="'+this._q.replace(/"/g,'&quot;')+'" style="flex:2;min-width:180px;padding:7px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:6px;color:var(--text1);font-size:12px">'+
        '<input id="ar-country" placeholder="国家（精确，如：巴基斯坦）" value="'+this._country.replace(/"/g,'&quot;')+'" style="flex:1;min-width:150px;padding:7px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:6px;color:var(--text1);font-size:12px">'+
        '<select id="ar-type" style="padding:7px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:6px;color:var(--text1);font-size:12px">'+typeOpts+'</select>'+
        '<input id="ar-since" type="date" value="'+this._since+'" style="padding:7px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:6px;color:var(--text1);font-size:12px">'+
        '<span style="color:var(--text3);font-size:11px">至</span>'+
        '<input id="ar-until" type="date" value="'+this._until+'" style="padding:7px 10px;background:var(--bg2);border:1px solid var(--border);border-radius:6px;color:var(--text1);font-size:12px">'+
        '<span class="dc-tab" id="ar-search" style="cursor:pointer">🔍 检索</span>'+
      '</div>'+
      '<div id="ar-stats"></div>'+
      '<div id="ar-results"></div>'+
      '<div id="ar-pager" style="display:flex;gap:10px;align-items:center;justify-content:center;margin-top:12px"></div></div>';
    document.getElementById('ar-search').onclick=function(){ self._page=1; self._readForm(); self._load(); };
    [ 'ar-q','ar-country' ].forEach(function(id){ document.getElementById(id).onkeydown=function(ev){ if(ev.key==='Enter'){ self._page=1; self._readForm(); self._load(); } }; });
    this._load();
  },
  _readForm(){
    this._q=document.getElementById('ar-q').value.trim();
    this._country=document.getElementById('ar-country').value.trim();
    this._type=document.getElementById('ar-type').value;
    this._since=document.getElementById('ar-since').value;
    this._until=document.getElementById('ar-until').value;
  },
  _load(){
    var self=this;
    var res=document.getElementById('ar-results');
    if(res) res.innerHTML='<div style="padding:24px;text-align:center;color:var(--text3)">检索中…</div>';
    var qs=new URLSearchParams({page:String(this._page),limit:'20',q:this._q,country:this._country,type:this._type,since:this._since,until:this._until});
    fetch('/api/archive/search?'+qs.toString()).then(function(r){return r.json();}).then(function(d){
      self._data=d; self._render();
    }).catch(function(e){
      if(res) res.innerHTML='<div style="padding:24px;text-align:center;color:var(--orange)">归档检索失败：'+e.message+'</div>';
    });
  },
  _render(){
    if(!this._data) return;
    var self=this, d=this._data;
    var st=d.stats||{};
    var stHost=document.getElementById('ar-stats');
    if(stHost){
      var byC=(st.byCountry||[]).slice(0,8).map(function(r){return '<span class="badge" style="background:var(--bg2);color:var(--text2);margin:2px;cursor:pointer" onclick="ARCHIVE_VIEW._qCountry(\''+String(r.k).replace(/'/g,"\\'")+'\')">'+r.k+' '+r.c+'</span>';}).join('');
      stHost.innerHTML='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">'+
        '<div class="stat-card" style="flex:1;min-width:130px"><div class="stat-v" style="color:var(--cyan)">'+(d.total||0)+'</div><div class="stat-l">本条件命中</div></div>'+
        '<div class="stat-card" style="flex:1;min-width:130px"><div class="stat-v">'+(st.totalAll||0)+'</div><div class="stat-l">归档库总量</div></div>'+
        '<div class="stat-card" style="flex:2;min-width:200px"><div class="stat-v" style="font-size:13px;line-height:1.7">'+(st.minTime?new Date(st.minTime).toLocaleDateString('zh-CN'):'—')+' ~ '+(st.maxTime?new Date(st.maxTime).toLocaleDateString('zh-CN'):'—')+'</div><div class="stat-l">归档时间跨度</div></div>'+
      '</div>'+(byC?'<div style="margin-bottom:8px"><span style="font-size:11px;color:var(--text3)">国别 TOP（点击检索）：</span>'+byC+'</div>':'');
    }
    var host=document.getElementById('ar-results');
    if(!host) return;
    if(!d.rows||!d.rows.length){
      host.innerHTML='<div style="padding:28px;text-align:center;color:var(--text3)">归档库无命中记录<div style="font-size:11px;margin-top:6px">当前归档来自活跃库 7 天前滚动迁移，历史深度随系统运行累积</div></div>';
    } else {
      var html='<div class="table-wrap" style="max-height:480px;overflow-y:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--bg2)">'+
        '<th style="text-align:left;padding:7px 8px;font-size:11px;color:var(--text2)">归档时间</th>'+
        '<th style="text-align:left;padding:7px 8px;font-size:11px;color:var(--text2)">国家</th>'+
        '<th style="text-align:left;padding:7px 8px;font-size:11px;color:var(--text2)">类别</th>'+
        '<th style="text-align:left;padding:7px 8px;font-size:11px;color:var(--text2)">标题</th>'+
        '<th style="text-align:left;padding:7px 8px;font-size:11px;color:var(--text2)">来源</th></tr></thead><tbody>';
      d.rows.forEach(function(r){
        var t=new Date(r.time).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
        html+='<tr style="border-bottom:1px solid var(--border)">'+
          '<td style="padding:6px 8px;font-size:11px;color:var(--text3);white-space:nowrap">'+t+'</td>'+
          '<td style="padding:6px 8px;font-size:12px;color:var(--text1);white-space:nowrap">'+(r.country||'—')+'</td>'+
          '<td style="padding:6px 8px;font-size:11px;color:var(--cyan);white-space:nowrap">'+(r.type||'—')+'</td>'+
          '<td style="padding:6px 8px;font-size:12px;color:var(--text2)">'+(r.url?'<a href="'+r.url+'" target="_blank" style="color:var(--text2);text-decoration:none" onmouseover="this.style.color=\'var(--cyan)\'" onmouseout="this.style.color=\'var(--text2)\'">'+String(r.title).slice(0,90)+'</a>':String(r.title).slice(0,90))+'</td>'+
          '<td style="padding:6px 8px;font-size:11px;color:var(--text3);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(r.source||'—')+'</td></tr>';
      });
      html+='</tbody></table></div>';
      host.innerHTML=html;
    }
    var pager=document.getElementById('ar-pager');
    if(pager){
      var pages=Math.max(1,Math.ceil((d.total||0)/(d.limit||20)));
      pager.innerHTML=
        '<span class="dc-tab'+(this._page<=1?' dim':'')+'" style="cursor:'+(this._page<=1?'default':'pointer')+';'+(this._page<=1?'opacity:.4':'')+'" onclick="ARCHIVE_VIEW._pageTo('+(this._page-1)+')">‹ 上一页</span>'+
        '<span style="font-size:12px;color:var(--text2)">第 '+this._page+' / '+pages+' 页 · 共 '+(d.total||0)+' 条</span>'+
        '<span class="dc-tab'+(this._page>=pages?' dim':'')+'" style="cursor:'+(this._page>=pages?'default':'pointer')+';'+(this._page>=pages?'opacity:.4':'')+'" onclick="ARCHIVE_VIEW._pageTo('+(this._page+1)+')">下一页 ›</span>';
    }
  },
  _qCountry(cn){ this._country=cn; this._page=1; this.init(); },
  _pageTo(pg){ if(pg<1) return; this._page=pg; this._load(); }
};

/* 研判简报页签切换（周期研判 / 每日简报 合并视图） */
function switchAnalysisTab(t){
  var pp=document.getElementById('ana-pane-periodic'), pd=document.getElementById('ana-pane-daily');
  if(!pp||!pd)return;
  pp.style.display=(t==='periodic')?'':'none';
  pd.style.display=(t==='daily')?'':'none';
  document.querySelectorAll('#ana-tabs .dc-tab').forEach(function(e,i){e.classList.toggle('active',(i===0&&t==='periodic')||(i===1&&t==='daily'));});
  if(t==='daily'){ setTimeout(function(){ try{ if(typeof DAILY_REPORT!=='undefined') DAILY_REPORT.init(); }catch(e){ console.error('DAILY_REPORT.init错误:',e); } },0); }
  else { setTimeout(function(){ try{ if(typeof DATACENTER!=='undefined') DATACENTER.renderAnalysis(false,'analysis-body'); }catch(e){} },0); }
}

// ===== AUTH =====
const AUTH={
  user:null,
  _ready:false,   /* 2026-08-31 修竞态：app.js 加载完成前登录按钮可点导致 ReferenceError
                    引导页跳转后卡片立即渲染但 AUTH 还在加载——输入框/按钮置灰，
                    init/_localInit 完成置 _ready=true 后再激活；按钮 onclick 也兜底守卫 */
  get currentUser(){ return this.user; },
  init(){
    // 初始化 API 客户端（检测后端）
    if(typeof APIClient!=='undefined') APIClient.init();

    // 优先尝试 API token 恢复
    var self=this;
    if(typeof APIClient!=='undefined' && APIClient.getToken()){
      APIClient.checkAuth().then(function(user){
        self.user={name:user.name,role:user.role,isTrial:user.trial,expireTime:user.expireTime};
        try{localStorage.setItem('orps_user',JSON.stringify(self.user));}catch(e){}
        self.showApp();
      }).catch(function(){
        APIClient._clearToken();
        self._localInit();
      });
    }else{
      this._localInit();
    }
  },
  _localInit(){
    const u=localStorage.getItem('orps_user');
    if(u){try{this.user=JSON.parse(u);this.showApp();return;}catch(e){}}
    this.showLogin();
    this.startLoginAnim();
    /* 2026-08-31 修竞态：登录卡片已渲染后激活 AUTH._ready + 启用输入框/按钮，
       引导页跳转立即可点的卡不会因 AUTH 还在加载报 ReferenceError */
    this._ready = true;
    this._enableLoginUi();
  },
  _enableLoginUi(){
    var ids = ['li-user','li-pass'];
    ids.forEach(function(id){ var el = document.getElementById(id); if (el) { el.disabled = false; el.removeAttribute('aria-disabled'); } });
    var btns = document.querySelectorAll('#auth-card-login button.auth-btn');
    btns.forEach(function(b){ b.disabled = false; b.removeAttribute('aria-disabled'); b.style.opacity = ''; b.style.pointerEvents = ''; });
    var hint = document.getElementById('login-hint');
    if (hint) hint.style.display = 'none';
  },
  _countAccounts(){
    var n=0;
    for(var i=0;i<localStorage.length;i++){
      var k=localStorage.key(i);
      if(k&&k.indexOf('orps_acct_')===0)n++;
    }
    return n;
  },
  showSetup(){document.getElementById('auth-card-login').style.display='none';document.getElementById('auth-card-register').style.display='none';document.getElementById('auth-card-setup').style.display='block';},
  setupAdmin(){
    const u=document.getElementById('su-user').value.trim();
    const p=document.getElementById('su-pass').value.trim();
    const p2=document.getElementById('su-pass2').value.trim();
    if(!u||!p){showToast('请填写用户名和密码');return;}
    if(p.length<6){showToast('密码至少6位');return;}
    if(p!==p2){showToast('两次密码不一致');return;}
    var now=new Date().toLocaleString('zh-CN');
    localStorage.setItem('orps_acct_'+u,JSON.stringify({user:u,pass:p,status:'approved',role:'admin',regTime:now}));
    this.user={name:u,pass:p,role:'admin'};
    localStorage.setItem('orps_user',JSON.stringify(this.user));
    showToast('✅ 管理员账号创建成功！请牢记您的密码');
    this.showApp();
  },
  _animRAF:null,
  startLoginAnim(){
    const cv=document.getElementById('auth-canvas');
    if(!cv)return;
    const ctx=cv.getContext('2d');
    let W,H,t=0;
    const resize=()=>{W=cv.width=cv.offsetWidth;H=cv.height=cv.offsetHeight;};
    resize();window.addEventListener('resize',resize);
    // Key cities — Beijing-centric overseas interest protection network
    const cities=[
      {lat:39.9,lon:116.4},{lat:1.3,lon:103.8},{lat:25.3,lon:55.3},
      {lat:55.7,lon:37.6},{lat:51.5,lon:-0.1},{lat:40.7,lon:-74.0},
      {lat:-33.9,lon:151.2},{lat:6.5,lon:3.4},{lat:30.0,lon:31.2},
      {lat:35.7,lon:139.7},{lat:28.6,lon:77.2},{lat:14.6,lon:121.0},
    ];
    // Starfield — scattered twinkling stars
    const stars=[];
    for(let i=0;i<220;i++)stars.push({
      x:Math.random(),y:Math.random(),
      r:Math.random()*1.3+0.3,
      tw:Math.random()*6.28,
      sp:Math.random()*1.5+0.4,
      warm:Math.random()>0.88
    });
    // Big stars — with diffraction spikes
    const bigStars=[];
    for(let i=0;i<7;i++)bigStars.push({
      x:Math.random(),y:Math.random()*0.85,
      r:Math.random()*0.8+1.8,
      tw:Math.random()*6.28,
      sp:Math.random()*0.8+0.3,
      warm:Math.random()>0.5
    });
    // Meteors & comets
    const meteors=[];
    const comets=[];
    let nextMeteor=2+Math.random()*3;
    let nextComet=5+Math.random()*5;
    // 3D sphere → 2D projection
    const project=(lat,lon,rot,cx,cy,r)=>{
      const phi=(90-lat)*Math.PI/180;
      const theta=(lon+rot)*Math.PI/180;
      const x=cx+r*Math.sin(phi)*Math.cos(theta);
      const y=cy-r*Math.cos(phi);
      const z=r*Math.sin(phi)*Math.sin(theta);
      return{x,y,z};
    };
    const draw=()=>{
      t+=0.005;
      ctx.fillStyle='rgba(5,8,18,0.2)';
      ctx.fillRect(0,0,W,H);
      const gcx=W/2,gcy=H/2,gr=Math.min(W,H)*0.38,rot=t*8;
      // Starfield — twinkling
      stars.forEach(s=>{
        const tw=Math.sin(t*s.sp+s.tw)*0.45+0.55;
        const col=s.warm?'255,235,180':'210,225,255';
        ctx.fillStyle='rgba('+col+','+(0.15*tw+0.05)+')';
        ctx.beginPath();ctx.arc(s.x*W,s.y*H,s.r*tw,0,6.28);ctx.fill();
      });
      // Big stars — diffraction spike glow
      bigStars.forEach(s=>{
        const tw=Math.sin(t*s.sp+s.tw)*0.4+0.6;
        const col=s.warm?'255,240,200':'220,235,255';
        const sx=s.x*W,sy=s.y*H,sr=s.r*tw;
        // Glow halo
        const halo=ctx.createRadialGradient(sx,sy,0,sx,sy,sr*6);
        halo.addColorStop(0,'rgba('+col+','+(0.25*tw)+')');
        halo.addColorStop(1,'rgba('+col+',0)');
        ctx.fillStyle=halo;
        ctx.beginPath();ctx.arc(sx,sy,sr*6,0,6.28);ctx.fill();
        // Diffraction spikes
        ctx.strokeStyle='rgba('+col+','+(0.3*tw)+')';ctx.lineWidth=0.6;
        const spikeLen=sr*5;
        ctx.beginPath();
        ctx.moveTo(sx-spikeLen,sy);ctx.lineTo(sx+spikeLen,sy);
        ctx.moveTo(sx,sy-spikeLen);ctx.lineTo(sx,sy+spikeLen);
        ctx.stroke();
        // Core
        ctx.fillStyle='rgba(255,255,255,'+(0.9*tw)+')';
        ctx.beginPath();ctx.arc(sx,sy,sr,0,6.28);ctx.fill();
      });
      // Meteors — spawn occasionally, random direction
      nextMeteor-=0.005;
      if(nextMeteor<=0){
        nextMeteor=3+Math.random()*6;
        const spd=7+Math.random()*5;
        const goRight=Math.random()>0.5;
        const ang=Math.PI*0.12+Math.random()*Math.PI*0.2;
        if(goRight){
          meteors.push({x:Math.random()*W*0.5,y:-30,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,life:1,trail:[]});
        }else{
          meteors.push({x:W*0.5+Math.random()*W*0.5,y:-30,vx:-Math.cos(ang)*spd,vy:Math.sin(ang)*spd,life:1,trail:[]});
        }
      }
      for(let i=meteors.length-1;i>=0;i--){
        const m=meteors[i];
        m.trail.push({x:m.x,y:m.y});
        if(m.trail.length>18)m.trail.shift();
        m.x+=m.vx;m.y+=m.vy;m.life-=0.008;
        // Gradient trail
        if(m.trail.length>1){
          const g=ctx.createLinearGradient(m.trail[0].x,m.trail[0].y,m.x,m.y);
          g.addColorStop(0,'rgba(180,210,255,0)');
          g.addColorStop(0.7,'rgba(200,225,255,'+(m.life*0.35)+')');
          g.addColorStop(1,'rgba(255,255,255,'+m.life+')');
          ctx.strokeStyle=g;ctx.lineWidth=1.5;
          ctx.beginPath();ctx.moveTo(m.trail[0].x,m.trail[0].y);
          for(let j=1;j<m.trail.length;j++)ctx.lineTo(m.trail[j].x,m.trail[j].y);
          ctx.lineTo(m.x,m.y);ctx.stroke();
        }
        // Head
        ctx.fillStyle='rgba(255,255,255,'+m.life+')';
        ctx.beginPath();ctx.arc(m.x,m.y,1.5,0,6.28);ctx.fill();
        ctx.fillStyle='rgba(200,225,255,'+(m.life*0.2)+')';
        ctx.beginPath();ctx.arc(m.x,m.y,4,0,6.28);ctx.fill();
        if(m.life<=0||m.x>W+60||m.y>H+60)meteors.splice(i,1);
      }
      // Comets — larger, slower, wide glowing tail
      nextComet-=0.005;
      if(nextComet<=0){
        nextComet=8+Math.random()*10;
        const spd=3+Math.random()*2.5;
        const goRight=Math.random()>0.5;
        const ang=Math.PI*0.1+Math.random()*Math.PI*0.15;
        const tint=['120,255,200','150,220,255','200,180,255'][Math.floor(Math.random()*3)];
        if(goRight){
          comets.push({x:-40,y:Math.random()*H*0.4,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,life:1,trail:[],tint});
        }else{
          comets.push({x:W+40,y:Math.random()*H*0.4,vx:-Math.cos(ang)*spd,vy:Math.sin(ang)*spd,life:1,trail:[],tint});
        }
      }
      for(let i=comets.length-1;i>=0;i--){
        const m=comets[i];
        m.trail.push({x:m.x,y:m.y});
        if(m.trail.length>30)m.trail.shift();
        m.x+=m.vx;m.y+=m.vy;m.life-=0.004;
        // Wide gradient tail
        if(m.trail.length>1){
          const g=ctx.createLinearGradient(m.trail[0].x,m.trail[0].y,m.x,m.y);
          g.addColorStop(0,'rgba('+m.tint+',0)');
          g.addColorStop(0.6,'rgba('+m.tint+','+(m.life*0.15)+')');
          g.addColorStop(1,'rgba('+m.tint+','+(m.life*0.6)+')');
          ctx.strokeStyle=g;ctx.lineWidth=3;
          ctx.beginPath();ctx.moveTo(m.trail[0].x,m.trail[0].y);
          for(let j=1;j<m.trail.length;j++)ctx.lineTo(m.trail[j].x,m.trail[j].y);
          ctx.lineTo(m.x,m.y);ctx.stroke();
          // Inner bright core of tail
          const g2=ctx.createLinearGradient(m.trail[0].x,m.trail[0].y,m.x,m.y);
          g2.addColorStop(0,'rgba(255,255,255,0)');
          g2.addColorStop(1,'rgba(255,255,255,'+(m.life*0.4)+')');
          ctx.strokeStyle=g2;ctx.lineWidth=1;
          ctx.beginPath();ctx.moveTo(m.trail[0].x,m.trail[0].y);
          for(let j=1;j<m.trail.length;j++)ctx.lineTo(m.trail[j].x,m.trail[j].y);
          ctx.lineTo(m.x,m.y);ctx.stroke();
        }
        // Head — glowing coma
        const headGrad=ctx.createRadialGradient(m.x,m.y,0,m.x,m.y,8);
        headGrad.addColorStop(0,'rgba(255,255,255,'+m.life+')');
        headGrad.addColorStop(0.3,'rgba('+m.tint+','+(m.life*0.6)+')');
        headGrad.addColorStop(1,'rgba('+m.tint+',0)');
        ctx.fillStyle=headGrad;
        ctx.beginPath();ctx.arc(m.x,m.y,8,0,6.28);ctx.fill();
        if(m.life<=0||m.x>W+80||m.x<-80||m.y>H+80)comets.splice(i,1);
      }
      // Globe sphere fill — subtle 3D planet gradient
      const sphereGrad=ctx.createRadialGradient(gcx-gr*0.3,gcy-gr*0.3,0,gcx,gcy,gr);
      sphereGrad.addColorStop(0,'rgba(10,30,60,0.35)');
      sphereGrad.addColorStop(0.7,'rgba(6,16,35,0.2)');
      sphereGrad.addColorStop(1,'rgba(4,10,25,0.05)');
      ctx.fillStyle=sphereGrad;
      ctx.beginPath();ctx.arc(gcx,gcy,gr,0,6.28);ctx.fill();
      // Globe latitude lines — very subtle
      ctx.strokeStyle='rgba(0,212,255,0.035)';ctx.lineWidth=0.5;
      for(let lat=-60;lat<=60;lat+=30){
        ctx.beginPath();let first=true;
        for(let lon=0;lon<=360;lon+=4){
          const p=project(lat,lon,rot,gcx,gcy,gr);
          if(p.z>0){if(first){ctx.moveTo(p.x,p.y);first=false;}else ctx.lineTo(p.x,p.y);}
          else first=true;
        }
        ctx.stroke();
      }
      // Globe longitude lines — very subtle, fewer
      ctx.strokeStyle='rgba(0,212,255,0.03)';
      for(let lon=0;lon<360;lon+=30){
        ctx.beginPath();let first=true;
        for(let lat=-90;lat<=90;lat+=3){
          const p=project(lat,lon,rot,gcx,gcy,gr);
          if(p.z>0){if(first){ctx.moveTo(p.x,p.y);first=false;}else ctx.lineTo(p.x,p.y);}
          else first=true;
        }
        ctx.stroke();
      }
      // Equator — slightly brighter
      ctx.strokeStyle='rgba(0,212,255,0.06)';ctx.lineWidth=0.5;
      ctx.beginPath();
      let first=true;
      for(let lon=0;lon<=360;lon+=4){
        const p=project(0,lon,rot,gcx,gcy,gr);
        if(p.z>0){if(first){ctx.moveTo(p.x,p.y);first=false;}else ctx.lineTo(p.x,p.y);}
        else first=true;
      }
      ctx.stroke();
      // Globe outline — soft glow
      for(let i=0;i<4;i++){
        ctx.strokeStyle='rgba(0,212,255,'+(0.04-i*0.008)+')';ctx.lineWidth=1+i*1.5;
        ctx.beginPath();ctx.arc(gcx,gcy,gr+i*0.5,0,6.28);ctx.stroke();
      }
      ctx.strokeStyle='rgba(0,212,255,0.12)';ctx.lineWidth=1;
      ctx.beginPath();ctx.arc(gcx,gcy,gr,0,6.28);ctx.stroke();
      // City markers — simple dots
      cities.forEach((c,idx)=>{
        const p=project(c.lat,c.lon,rot,gcx,gcy,gr);
        if(p.z>0){
          const depth=p.z/gr;
          const isHub=idx===0;
          const col=isHub?'255,200,80':'0,212,255';
          const r=isHub?3:1.5;
          ctx.fillStyle='rgba('+col+','+(0.1*depth)+')';
          ctx.beginPath();ctx.arc(p.x,p.y,r*2.5,0,6.28);ctx.fill();
          ctx.fillStyle='rgba('+col+','+(0.85*depth)+')';
          ctx.beginPath();ctx.arc(p.x,p.y,r,0,6.28);ctx.fill();
        }
      });
      this._animRAF=requestAnimationFrame(draw);
    };
    draw();
  },
  stopLoginAnim(){if(this._animRAF)cancelAnimationFrame(this._animRAF);},
  login(){
    const u=document.getElementById('li-user').value.trim();
    const p=document.getElementById('li-pass').value.trim();
    if(!u||!p){showToast('请输入用户名和密码');return;}
    var self=this;
    // 优先尝试 API 登录（仅当数据库在线时；DB 离线则直接本地登录，避免 500 后闪错）
    if(typeof APIClient!=='undefined' && APIClient.isOnline() && APIClient.isDBOnline()){
      APIClient.login(u,p).then(function(data){
        self.user={name:data.user.name,role:data.user.role,isTrial:data.user.trial||false,expireTime:data.user.expireTime||null};
        localStorage.setItem('orps_user',JSON.stringify(self.user));
        self.showApp();
      }).catch(function(err){
        if(err.status===401||err.status===404){showToast(err.message||'用户名或密码错误');}
        else if(err.status===403){showToast(err.message||'账号未审核或已过期');}
        else{
          console.warn('[AUTH.login] API 登录失败，状态:',err&&err.status,'降级本地登录');
          showToast('服务器连接失败，尝试本地登录...');
          setTimeout(function(){self._localLogin(u,p);},300);
        }
      });
      return;
    }
    this._localLogin(u,p);
  },
  _localLogin(u,p){
    const stored=localStorage.getItem('orps_acct_'+u);
    if(!stored){showToast('账号不存在，请先注册或联系管理员');return;}
    acct=JSON.parse(stored);
    if(acct.pass!==p){showToast('密码错误');return;}
    if(acct.status==='pending'){showToast('账号待审批，请联系管理员授权');return;}
    if(acct.status==='rejected'){showToast('账号已被拒绝，请联系管理员');return;}
    if(acct.status==='disabled'){showToast('账号已被停用，请联系管理员');return;}
    if(acct.status==='expired'){showToast('试用账号已过期，请联系管理员续期');return;}
    if(acct.status!=='approved'){showToast('账号状态异常，请联系管理员');return;}
    // 试用账号到期检查
    if(acct.isTrial&&acct.expireTime){
      var now=new Date().getTime();
      var expire=this._parseTime(acct.expireTime);
      if(!isNaN(expire)&&now>expire){
        acct.status='expired';
        localStorage.setItem('orps_acct_'+u,JSON.stringify(acct));
        showToast('试用账号已过期，请联系管理员续期');
        return;
      }
    }
    this.user={name:u,pass:p,role:acct.role||'user',isTrial:acct.isTrial||false,expireTime:acct.expireTime||null};
    localStorage.setItem('orps_user',JSON.stringify(this.user));
    this.showApp();
  },
  register(){
    const u=document.getElementById('rg-user').value.trim();
    const p=document.getElementById('rg-pass').value.trim();
    const p2=document.getElementById('rg-pass2').value.trim();
    if(!u||!p){showToast('请填写用户名和密码');return;}
    if(p!==p2){showToast('两次密码不一致');return;}
    if(u==='admin'){showToast('该用户名已被保留');return;}
    // 优先使用 API 注册
    if(typeof APIClient!=='undefined' && APIClient.isOnline()){
      var self=this;
      APIClient.register(u,p).then(function(){showToast('注册成功！账号待管理员审批，审批通过后方可登录');self.showLogin();})
        .catch(function(err){showToast(err.message||'注册失败，请重试');});
      return;
    }
    // localStorage 回退
    if(localStorage.getItem('orps_acct_'+u)){showToast('用户名已存在');return;}
    var now=new Date().toLocaleString('zh-CN');
    localStorage.setItem('orps_acct_'+u,JSON.stringify({user:u,pass:p,status:'pending',role:'user',regTime:now}));
    showToast('注册成功！账号待管理员审批，审批通过后方可登录');
    this.showLogin();
  },
  showReg(){document.getElementById('auth-card-login').style.display='none';document.getElementById('auth-card-register').style.display='block';},
  showLogin(){document.getElementById('auth-card-login').style.display='block';document.getElementById('auth-card-register').style.display='none';},
  showApp(){
    this.stopLoginAnim();
    document.getElementById('auth-overlay').style.display='none';
    document.getElementById('app').style.display='flex';
    document.getElementById('tb-avatar').textContent=this.user.name[0].toUpperCase();
    document.getElementById('tb-username').textContent=this.user.name;
    var roleEl=document.getElementById('tb-userrole');
    if(roleEl){if(this.user.role==='admin'){roleEl.style.display='inline-block';}else{roleEl.style.display='none';}}
    // 检测 navigateTo 是否可用（调试）
    if(typeof navigateTo!=='function'){
      console.error('[CRITICAL] navigateTo 未定义！app.js 未完全加载');
      alert('⚠️ 系统加载不完整，请刷新页面\n\nnavigateTo 函数不存在');
    }else{
      console.log('[OK] navigateTo 已定义，类型:',typeof navigateTo);
    }
    // 试用账号到期提醒
    var trialInfo=this.checkTrialStatus();
    if(trialInfo){
      var trialBadge=document.getElementById('tb-pending-users');
      if(trialBadge){
        trialBadge.style.display='block';
        trialBadge.style.background='rgba(0,212,255,0.12)';
        trialBadge.style.border='1px solid rgba(0,212,255,0.3)';
        trialBadge.style.color='var(--cyan)';
        trialBadge.textContent='\u{1F3DB}\uFE0F \u8bd5\u7528\u8d26\u53f7 \u5269'+trialInfo.remain+'\u5929';
        trialBadge.title='\u5230\u671f\u65f6\u95f4: '+trialInfo.expireTime;
        trialBadge.onclick=function(){navigateTo('settings');};
      }
      if(trialInfo.remain<=3){
        showToast('\u26a0\ufe0f \u8bd5\u7528\u8d26\u53f7\u5c06\u4e8e '+trialInfo.remain+' \u5929\u540e\u5230\u671f\uff0c\u8bf7\u8054\u7cfb\u7ba1\u7406\u5458\u7eed\u671f');
      }
    }
    try{
      /* IndexedDB 持久层就绪门控：内存层未水合完成前不启动 initApp，
       * 避免 DBCenter/DataHub 从空存储初始化导致数据"丢失"假象 */
      if(window.IDBStore&&!IDBStore.ready()){
        var _retry=0;
        var _waitIDB=function(){
          if(IDBStore.ready()||++_retry>50){ try{initApp();}catch(e){console.error('[initApp] 崩溃:',e&&e.message);showToast('⚠️ 系统初始化异常，请刷新页面');} }
          else setTimeout(_waitIDB,80);
        };
        _waitIDB();
      }else{
        initApp();
      }
    }catch(e){
      console.error('[initApp] 崩溃:',e&&e.message);
      showToast('⚠️ 系统初始化异常，请刷新页面');
    }
  },
  logout(){if(typeof APIClient!=='undefined')APIClient.logout();localStorage.removeItem('orps_user');location.reload();},
  // 创建试用账号
  createTrialAccount(username,password,days,note){
    if(!PERM.isAdmin()){showToast('仅管理员可创建试用账号');return false;}
    if(!username||!password){showToast('请填写用户名和密码');return false;}
    // 优先使用 API
    if(typeof APIClient!=='undefined' && APIClient.isOnline()){
      APIClient.createTrial(username,password,days).then(function(){
        showToast('试用账号创建成功: '+username+' (有效期'+days+'天)');
      }).catch(function(err){showToast(err.message||'创建失败');});
      return true;
    }
    // localStorage 回退
    if(localStorage.getItem('orps_acct_'+username)){showToast('用户名已存在');return false;}
    var now=new Date();
    var expire=new Date(now.getTime()+days*24*60*60*1000);
    var acct={
      user:username,
      pass:password,
      status:'approved',
      role:'user',
      isTrial:true,
      createTime:now.toLocaleString('zh-CN'),
      expireTime:expire.toISOString(),
      note:note||'',
      regTime:now.toLocaleString('zh-CN')
    };
    localStorage.setItem('orps_acct_'+username,JSON.stringify(acct));
    showToast('试用账号创建成功: '+username+' (有效期'+days+'天)');
    return true;
  },
  // 续期试用账号
  renewTrial(username,days){
    // 优先使用 API
    if(typeof APIClient!=='undefined' && APIClient.isOnline()){
      APIClient.renewTrial(username,days).then(function(data){
        showToast('续期成功，新到期时间: '+new Date(data.expireTime).toLocaleString('zh-CN'));
      }).catch(function(err){showToast(err.message||'续期失败');});
      return;
    }
    // localStorage 回退
    var stored=localStorage.getItem('orps_acct_'+username);
    if(!stored){showToast('账号不存在');return;}
    var acct=JSON.parse(stored);
    if(!acct.isTrial){showToast('非试用账号');return;}
    var baseTime=acct.expireTime?new Date(acct.expireTime).getTime():new Date().getTime();
    var now=new Date().getTime();
    var startTime=Math.max(baseTime,now);
    var newExpire=new Date(startTime+days*24*60*60*1000);
    acct.expireTime=newExpire.toISOString();
    if(acct.status==='expired')acct.status='approved';
    localStorage.setItem('orps_acct_'+username,JSON.stringify(acct));
    showToast('已续期 '+days+' 天，新到期时间: '+acct.expireTime);
  },
  // 检查当前用户试用状态
  checkTrialStatus(){
    if(!this.user||!this.user.isTrial)return null;
    if(!this.user.expireTime)return null;
    var expire=this._parseTime(this.user.expireTime);
    if(!expire||isNaN(expire))return null;
    var now=new Date().getTime();
    var remain=Math.ceil((expire-now)/(24*60*60*1000));
    return {remain:remain,expireTime:this.user.expireTime};
  },
  // 安全解析日期时间（兼容 ISO 8601 和 toLocaleString 格式）
  _parseTime(timeStr){
    if(!timeStr)return NaN;
    // 优先尝试直接解析
    var d=new Date(timeStr);
    if(!isNaN(d.getTime()))return d.getTime();
    // 尝试替换中文日期格式（如 "2026年8月14日 上午8:49:29"）
    var cleaned=timeStr
      .replace(/年/g,'/').replace(/月/g,'/').replace(/日/g,' ')
      .replace(/上午/g,'AM').replace(/下午/g,'PM')
      .replace(/[\u2009\u00A0]/g,' '); // thin space / nbsp
    d=new Date(cleaned);
    if(!isNaN(d.getTime()))return d.getTime();
    return NaN;
  }
};

/* ============================================================
 * WORLDGEO — 真实世界地理底图层（2026-08-29 用户指令：地球/平面地图都得有地图层）
 * 数据源：项目自带 countries-110m.json（Natural Earth 110m，与 Leaflet 底图同源）
 * 提供：land 大陆轮廓 / china 中国轮廓（含台湾，地图合规）/ borders 国界线
 * ============================================================ */
const WORLDGEO={
  _p:null,
  load(){
    if(!this._p){
      this._p=fetch('countries-110m.json').then(function(r){return r.json();}).then(function(w){
        var land=topojson.feature(w,w.objects.land);
        var countries=topojson.feature(w,w.objects.countries);
        /* 中国 = China feature + 台湾（中国地图合规：台湾是中国一部分，必须并入） */
        var chinaPolys=[];
        countries.features.forEach(function(f){
          var nm=f.properties&&f.properties.name;
          if(nm==='China'||nm==='Taiwan'){
            var g=f.geometry;
            if(g.type==='Polygon')chinaPolys.push([g.coordinates]);
            else if(g.type==='MultiPolygon')chinaPolys.push.apply(chinaPolys,g.coordinates);
          }
        });
        var borders=topojson.mesh(w,w.objects.countries,function(a,b){return a!==b;});
        return {land:land.features[0],chinaPolys:chinaPolys,borders:borders};
      }).catch(function(e){
        console.warn('[WORLDGEO] 轮廓数据加载失败，地图层回退点阵:',e);
        return null;
      });
    }
    return this._p;
  }
};

// ===== GLOBE — Overseas Interest Protection Intelligence Globe =====
const GLOBE={
  canvas:null,ctx:null,rotation:0,tilt:0,autoRotate:true,
  isDragging:false,dragStartX:0,dragStartRot:0,dragStartY:0,dragStartTilt:0,
  _stars:null,_landDots:null,_chinaDots:null,_protectLines:null,_tradeRoutes:null,_nodes:null,_wideOrbits:null,
  _scanAngle:0,_time:0,
  BEIJING:{lat:39.9,lon:116.4},
  _chokepoints:[
    {name:'曼德海峡',lat:12.6,lon:43.4},
    {name:'苏伊士运河',lat:30.0,lon:32.5},
    {name:'马六甲海峡',lat:2.5,lon:101.3},
    {name:'霍尔木兹海峡',lat:26.6,lon:56.3},
    {name:'巴拿马运河',lat:9.1,lon:-79.7},
    {name:'北极航道',lat:78.0,lon:140.0}
  ],
  init(){
    this.canvas=document.getElementById('globe-canvas');
    if(!this.canvas)return;
    this.ctx=this.canvas.getContext('2d');
    const c=this.canvas.parentElement;
    this.canvas.width=c.clientWidth;
    this.canvas.height=500;
    /* 平面地图模式（COSRI 对标：地球/平面一键切换） */
    this.mode=localStorage.getItem('orps_globe_mode')||'globe';
    this._applyModeUI();
    if(this.mode==='flat' && typeof FLATMAP!=='undefined') FLATMAP.init();
    this.canvas.addEventListener('click',e=>{
      if(this.mode==='flat')return;
      const hit=this._hitCountry(e);
      if(hit && typeof COUNTRY_DRAWER!=='undefined') COUNTRY_DRAWER.open(hit);
    });
    this.canvas.addEventListener('mousedown',e=>{this.isDragging=true;this.dragStartX=e.clientX;this.dragStartY=e.clientY;this.dragStartRot=this.rotation;this.dragStartTilt=this.tilt;this.autoRotate=false;});
    this.canvas.addEventListener('mousemove',e=>{
      if(this.isDragging){
        this.rotation=this.dragStartRot+(e.clientX-this.dragStartX)*0.5;
        this.tilt=Math.max(-45,Math.min(45,this.dragStartTilt-(e.clientY-this.dragStartY)*0.3));
      }
      const rect=this.canvas.getBoundingClientRect();
      const mx=e.clientX-rect.left,my=e.clientY-rect.top;
      const cx=this.canvas.width/2,cy=this.canvas.height/2;
      const r=Math.min(this.canvas.width*0.30,this.canvas.height*0.42);
      const dx=(mx-cx)/r,dy=(my-cy)/r;
      if(dx*dx+dy*dy<1){
        const lat=Math.asin(-dy)*180/Math.PI;
        const lon=Math.atan2(dx,Math.cos(lat*Math.PI/180))*180/Math.PI-this.rotation;
        const el=document.getElementById('globe-hud-coord');
        if(el)el.textContent='LAT '+lat.toFixed(1)+'°  LON '+((lon+540)%360-180).toFixed(1)+'°';
      }
    });
    this.canvas.addEventListener('mouseup',()=>{this.isDragging=false;setTimeout(()=>{this.autoRotate=true;},3000);});
    this.canvas.addEventListener('mouseleave',()=>{this.isDragging=false;});
    this.canvas.addEventListener('touchstart',e=>{e.preventDefault();const t=e.touches[0];this.isDragging=true;this.dragStartX=t.clientX;this.dragStartY=t.clientY;this.dragStartRot=this.rotation;this.dragStartTilt=this.tilt;this.autoRotate=false;},{passive:false});
    this.canvas.addEventListener('touchmove',e=>{e.preventDefault();const t=e.touches[0];if(this.isDragging){this.rotation=this.dragStartRot+(t.clientX-this.dragStartX)*0.5;this.tilt=Math.max(-45,Math.min(45,this.dragStartTilt-(t.clientY-this.dragStartY)*0.3));}},{passive:false});
    this.canvas.addEventListener('touchend',()=>{this.isDragging=false;setTimeout(()=>{this.autoRotate=true;},3000);});
    window.addEventListener('resize',()=>{if(this.canvas){this.canvas.width=this.canvas.parentElement.clientWidth;this.canvas.height=500;this._stars=null;this._nodes=null;}});
    if(!this._landDots)this._genLandDots();
    if(!this._protectLines)this._genProtectLines();
    if(!this._tradeRoutes)this._genTradeRoutes();
    /* 真实地理底图层（2026-08-29）：加载成功后 draw() 用大陆轮廓替代点阵 */
    if(!this._geoLoading){
      this._geoLoading=true;
      var self=this;
      WORLDGEO.load().then(function(g){if(g)self._geo=g;});
    }
    this.animate();
  },
  /* 单位球 3D 坐标（正交投影内部量）：lat/lon 度 → [x,y,z]，z>0 为可见半球 */
  _xyz(lat,lon,rot,tilt){
    const lr=lat*Math.PI/180,lor=(lon+rot)*Math.PI/180;
    const tr=(tilt||0)*Math.PI/180;
    const x0=Math.cos(lr)*Math.sin(lor);
    const y0=-Math.sin(lr);
    const z0=Math.cos(lr)*Math.cos(lor);
    const y1=y0*Math.cos(tr)-z0*Math.sin(tr);
    const z1=y0*Math.sin(tr)+z0*Math.cos(tr);
    return [x0,y1,z1];
  },
  /* 多边形环 → canvas 路径（含地平线精确裁剪：3D 线性插值求 z=0 交点） */
  _ringPath(ctx,ring,cx,cy,r,rot,tilt){
    const n=ring.length;
    if(n<2)return;
    let open=false,prev=null;
    for(let i=0;i<=n;i++){
      const v=ring[i%n];
      const P=this._xyz(v[1],v[0],rot,tilt);
      if(P[2]>0){
        if(!open){
          let sx=P[0],sy=P[1];
          if(prev&&prev[2]<=0&&prev[2]-P[2]!==0){
            const t=prev[2]/(prev[2]-P[2]);
            sx=prev[0]+t*(P[0]-prev[0]);sy=prev[1]+t*(P[1]-prev[1]);
          }
          ctx.moveTo(cx+sx*r,cy+sy*r);
          open=true;
        }else{
          ctx.lineTo(cx+P[0]*r,cy+P[1]*r);
        }
      }else if(open&&prev&&prev[2]>0&&prev[2]-P[2]!==0){
        const t=prev[2]/(prev[2]-P[2]);
        const hx=prev[0]+t*(P[0]-prev[0]),hy=prev[1]+t*(P[1]-prev[1]);
        ctx.lineTo(cx+hx*r,cy+hy*r);
        open=false;
      }
      prev=P;
    }
  },
  /* 折线（国界 mesh / 航线）→ canvas 路径，不可见段断开 */
  _linePath(ctx,line,cx,cy,r,rot,tilt){
    let open=false;
    for(let i=0;i<line.length;i++){
      const v=line[i];
      const P=this._xyz(v[1],v[0],rot,tilt);
      if(P[2]>0){
        if(!open){ctx.moveTo(cx+P[0]*r,cy+P[1]*r);open=true;}
        else ctx.lineTo(cx+P[0]*r,cy+P[1]*r);
      }else open=false;
    }
  },
  /* 真实大陆轮廓层：陆块 + 中国金色高亮 + 国界线 */
  _drawGeoLand(ctx,cx,cy,r,tilt){
    const geo=this._geo;
    if(!geo)return;
    const rot=this.rotation;
    /* 陆块 */
    ctx.beginPath();
    const polys=geo.land.geometry.type==='Polygon'?[geo.land.geometry.coordinates]:geo.land.geometry.coordinates;
    polys.forEach(poly=>poly.forEach(ring=>this._ringPath(ctx,ring,cx,cy,r,rot,tilt)));
    ctx.fillStyle='rgba(16,52,86,0.85)';
    ctx.fill();
    ctx.strokeStyle='rgba(0,212,255,0.30)';
    ctx.lineWidth=0.6;
    ctx.stroke();
    /* 国界线 */
    ctx.beginPath();
    geo.borders.coordinates.forEach(line=>this._linePath(ctx,line,cx,cy,r,rot,tilt));
    ctx.strokeStyle='rgba(0,212,255,0.12)';
    ctx.lineWidth=0.4;
    ctx.stroke();
    /* 中国（含台湾）金色高亮 */
    ctx.beginPath();
    geo.chinaPolys.forEach(poly=>poly.forEach(ring=>this._ringPath(ctx,ring,cx,cy,r,rot,tilt)));
    ctx.fillStyle='rgba(255,200,60,0.22)';
    ctx.fill();
    ctx.strokeStyle='rgba(255,200,60,0.6)';
    ctx.lineWidth=0.8;
    ctx.stroke();
  },
  _genLandDots(){
    const dots=[],chinaDots=[];
    const N=1800;
    const ga=Math.PI*(3-Math.sqrt(5));
    for(let i=0;i<N;i++){
      const y=1-(i/(N-1))*2;
      const r=Math.sqrt(1-y*y);
      const theta=ga*i;
      const lat=Math.asin(y)*180/Math.PI;
      const lon=(theta*180/Math.PI)%360-180;
      if(this._isLand(lat,lon)){
        if(this._isChina(lat,lon))chinaDots.push({lat,lon});
        else dots.push({lat,lon});
      }
    }
    this._landDots=dots;
    this._chinaDots=chinaDots;
  },
  _isChina(lat,lon){
    if(lat>=18&&lat<=53&&lon>=73&&lon<=135){
      if(lat<20&&lon<78)return false;
      if(lat<22&&lon>108)return false;
      if(lat>42&&lon>120&&lat<50)return true;
      if(lat<25&&lon>100&&lon<110&&lat>18)return false;
      if(lat<15&&lon>108)return false;
      if(lat>45&&lon<80&&lon>70)return false;
      return true;
    }
    return false;
  },
  _isLand(lat,lon){
    while(lon>180)lon-=360;while(lon<-180)lon+=360;
    // Africa
    if(lat>=-35&&lat<=37){
      if(lon>=-18&&lon<=52){
        if(lat>33)return true;
        if(lat>=5&&lat<=33&&lon>=-18&&lon<=42){
          if(lat>30&&lon<10&&lat<35)return true;
          if(lat>12&&lon>32&&lat<30)return false;
          return true;
        }
        if(lat>=2&&lat<=18&&lon>=35&&lon<=52)return true;
        if(lat>=-35&&lat<5&&lon>=8&&lon<=42){
          if(lat<-15&&lon>35&&lat>-25)return false;
          return true;
        }
        if(lat>=-5&&lat<15&&lon>=-18&&lon<8)return true;
        if(lat>=-15&&lat<5&&lon>=8&&lon<=18)return true;
        if(lat>=-35&&lat<-15&&lon>=10&&lon<=20)return true;
      }
    }
    if(lat>=-26&&lat<=-12&&lon>=43&&lon<=51)return true;
    // Europe
    if(lat>=36&&lat<=71){
      if(lon>=-10&&lon<=40){
        if(lat>41&&lat<47&&lon>28&&lon<42)return false;
        if(lat>37&&lat<41&&lon>12&&lon<18&&lat<40)return false;
        if(lat>43&&lat<46&&lon>27&&lon<30)return false;
        return true;
      }
      if(lat>=55&&lat<=71&&lon>=5&&lon<=32)return true;
      if(lat>=45&&lat<=60&&lon>=28&&lon<=60)return true;
    }
    if(lat>=50&&lat<=59&&lon>=-10&&lon<=2)return true;
    if(lat>=63&&lat<=67&&lon>=-24&&lon<=-13)return true;
    // Middle East
    if(lat>=12&&lat<=42&&lon>=35&&lon<=63){
      if(lat>25&&lat<40&&lon>50&&lon<58&&lat<35)return false;
      return true;
    }
    // Asia
    if(lat>=8&&lat<=75){
      if(lat>=50&&lon>=40&&lon<=180)return true;
      if(lat>=35&&lat<=50&&lon>=50&&lon<=87)return true;
      if(lat>=18&&lat<=53&&lon>=73&&lon<=135){
        if(this._isChina(lat,lon))return true;
        if(lat<22&&lon>95&&lon<100)return false;
        if(lat<18&&lon>95)return false;
      }
      if(lat>=8&&lat<=35&&lon>=68&&lon<=92)return true;
      if(lat>=8&&lat<=28&&lon>=92&&lon<=110){
        if(lat<10&&lon>98)return false;
        return true;
      }
      if(lat>=30&&lat<=46&&lon>=128&&lon<=146)return true;
      if(lat>=33&&lat<=43&&lon>=124&&lon<=131)return true;
      if(lat>=5&&lat<=19&&lon>=117&&lon<=127)return true;
      if(lat>=-10&&lat<=7&&lon>=95&&lon<=141)return true;
      if(lat>=-11&&lat<=-1&&lon>=131&&lon<=151)return true;
    }
    // North America
    if(lat>=15&&lat<=75&&lon>=-170&&lon<=-52){
      if(lat>=55&&lon>=-170&&lon<=-130)return true;
      if(lat>=49&&lon>=-130&&lon<=-55)return true;
      if(lat>=25&&lat<=49&&lon>=-125&&lon<=-67){
        if(lat>18&&lat<30&&lon>-98&&lon<-80)return false;
        return true;
      }
      if(lat>=15&&lat<=32&&lon>=-118&&lon<=-86)return true;
      if(lat>=7&&lat<=22&&lon>=-92&&lon<=-77)return true;
    }
    // Greenland
    if(lat>=60&&lat<=83&&lon>=-55&&lon<=-20){
      if(lat<65&&lon>-35&&lon<-25)return false;
      return true;
    }
    // South America
    if(lat>=-55&&lat<=12&&lon>=-82&&lon<=-34){
      if(lat<-5&&lon>-75&&lon<-70&&lat>-20)return false;
      if(lat<5&&lon>-78&&lon<-70&&lat>0)return false;
      return true;
    }
    // Australia
    if(lat>=-39&&lat<=-10&&lon>=113&&lon<=154)return true;
    // New Zealand
    if(lat>=-47&&lat<=-34&&lon>=166&&lon<=178)return true;
    return false;
  },
  _genProtectLines(){
    const entCountries=[...new Set(ENTERPRISES.flatMap(e=>e.countries))]
      .map(n=>COUNTRIES.find(c=>c.name===n))
      .filter(c=>c&&c.name!=='中国');
    this._protectLines=entCountries.map(c=>{
      const risk=calcOverall(c.scores);
      const ents=getEntsInCountry(c.name).length;
      return{
        from:{lat:this.BEIJING.lat,lon:this.BEIJING.lon},
        to:{lat:c.lat,lon:c.lon},
        risk:risk,ents:ents,name:c.name,
        progress:Math.random(),speed:0.003+Math.random()*0.004
      };
    });
  },
  _genTradeRoutes(){
    const routeDefs=[
      {from:{lat:39.9,lon:116.4},to:{lat:25.1,lon:62.3}},
      {from:{lat:39.9,lon:116.4},to:{lat:19.7,lon:96.5}},
      {from:{lat:39.9,lon:116.4},to:{lat:41.3,lon:69.2}},
      {from:{lat:39.9,lon:116.4},to:{lat:18.0,lon:102.6}},
      {from:{lat:39.9,lon:116.4},to:{lat:-6.2,lon:106.8}},
      {from:{lat:39.9,lon:116.4},to:{lat:37.9,lon:23.7}},
      {from:{lat:39.9,lon:116.4},to:{lat:30.0,lon:32.5}}
    ];
    this._tradeRoutes=routeDefs.map(r=>({...r,progress:Math.random(),speed:0.002+Math.random()*0.003}));
  },
  animate(){
    if(this.autoRotate)this.rotation+=0.18;
    this._time+=1;
    this._scanAngle=(this._scanAngle+0.012)%(Math.PI*2);
    if(this._protectLines)this._protectLines.forEach(a=>{a.progress+=a.speed;if(a.progress>1)a.progress=0;});
    if(this._tradeRoutes)this._tradeRoutes.forEach(a=>{a.progress+=a.speed;if(a.progress>1)a.progress=0;});
    if(this.mode==='flat'){
      if(typeof FLATMAP!=='undefined')FLATMAP.draw();
    }else{
      this.draw();
    }
    requestAnimationFrame(()=>this.animate());
  },
  /* ===== 平面地图/转动地球 切换（COSRI 对标 P0-1） ===== */
  setMode(m){
    this.mode=m;
    try{localStorage.setItem('orps_globe_mode',m);}catch(e){}
    this._applyModeUI();
    if(m==='flat'){
      if(typeof FLATMAP!=='undefined')FLATMAP.init();
    }else{
      this._stars=null;this._nodes=null; /* 切回地球重建星空层 */
    }
  },
  _applyModeUI(){
    var gc=this.canvas,bg=document.getElementById('gm-globe'),bf=document.getElementById('gm-flat');
    var fc=document.getElementById('flatmap-canvas');
    if(!gc)return;
    if(this.mode==='flat'){
      gc.classList.add('hide');
      if(fc){fc.classList.add('show');if(fc.width!==gc.width){fc.width=gc.width;fc.height=500;}}
      if(bf)bf.classList.add('active');
      if(bg)bg.classList.remove('active');
    }else{
      gc.classList.remove('hide');
      if(fc)fc.classList.remove('show');
      if(bg)bg.classList.add('active');
      if(bf)bf.classList.remove('active');
    }
  },
  /* 鼠标事件 → 命中国家（地球模式：3D 反投影找最近标记点；平面模式交给 FLATMAP） */
  _hitCountry(e){
    const rect=this.canvas.getBoundingClientRect();
    const mx=e.clientX-rect.left,my=e.clientY-rect.top;
    const w=this.canvas.width,h=this.canvas.height;
    const cx=w/2,cy=h/2,r=Math.min(w*0.30,h*0.42);
    let best=null,bestD=14; /* 命中半径 px */
    COUNTRIES.forEach(c=>{
      if(c.name==='中国')return;
      const p=this._ll2xy(c.lat,c.lon,cx,cy,r,this.rotation,this.tilt);
      if(!p.v)return;
      const d=Math.hypot(p.x-mx,p.y-my);
      if(d<bestD){bestD=d;best=c.name;}
    });
    return best;
  },
  _ll2xy(lat,lon,cx,cy,r,rot,tilt){
    const lr=lat*Math.PI/180,lor=(lon+rot)*Math.PI/180;
    const tr=(tilt||0)*Math.PI/180;
    const x0=r*Math.cos(lr)*Math.sin(lor);
    const y0=-r*Math.sin(lr);
    const z0=r*Math.cos(lr)*Math.cos(lor);
    const y1=y0*Math.cos(tr)-z0*Math.sin(tr);
    const z1=y0*Math.sin(tr)+z0*Math.cos(tr);
    return{x:cx+x0,y:cy+y1,z:z1,d:z1/r,v:z1>0};
  },
  draw(){
    const ctx=this.ctx,w=this.canvas.width,h=this.canvas.height;
    const cx=w/2,cy=h/2,r=Math.min(w*0.30,h*0.42);
    const tilt=this.tilt;
    // Deep space background
    const bg=ctx.createRadialGradient(cx,cy,0,cx,cy,Math.max(w,h)*0.7);
    bg.addColorStop(0,'#0a1428');bg.addColorStop(0.5,'#070b14');bg.addColorStop(1,'#030508');
    ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
    // Stars
    if(!this._stars){
      this._stars=[];
      for(let i=0;i<200;i++)this._stars.push({x:Math.random()*w,y:Math.random()*h,s:Math.random()*1.8+0.2,p:Math.random()*Math.PI*2,sp:0.015+Math.random()*0.04});
    }
    this._stars.forEach(s=>{
      const tw=Math.sin(this._time*s.sp+s.p)*0.3+0.7;
      ctx.fillStyle='rgba('+(s.s>1.2?'180,220,255':'100,140,180')+','+(tw*0.5)+')';
      ctx.fillRect(s.x,s.y,s.s,s.s);
    });
    // Futuristic backdrop layer (constellation / wide escort orbits / tech rings / scan beam / spectrum walls)
    this._drawBackdrop(ctx,w,h,cx,cy,r);
    // Atmosphere glow (4 layers)
    for(let i=3;i>=0;i--){
      const ag=ctx.createRadialGradient(cx,cy,r*0.92,cx,cy,r*(1.2+i*0.14));
      const alpha=0.1-i*0.025;
      ag.addColorStop(0,'rgba(0,180,255,'+alpha+')');
      ag.addColorStop(0.5,'rgba(0,150,255,'+(alpha*0.4)+')');
      ag.addColorStop(1,'rgba(0,212,255,0)');
      ctx.fillStyle=ag;ctx.fillRect(0,0,w,h);
    }
    // Sphere with 3D lighting
    const sg=ctx.createRadialGradient(cx-r*0.3,cy-r*0.3,r*0.05,cx,cy,r*1.1);
    sg.addColorStop(0,'rgba(12,28,50,0.95)');
    sg.addColorStop(0.5,'rgba(6,14,28,0.9)');
    sg.addColorStop(1,'rgba(2,5,10,0.95)');
    ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle=sg;ctx.fill();
    // 真实地理底图层（2026-08-29：大陆轮廓多边形，加载失败回退点阵）
    if(this._geo){
      this._drawGeoLand(ctx,cx,cy,r,tilt);
    }else{
      // Land dot-matrix fallback (cyan)
      if(this._landDots){
        this._landDots.forEach(d=>{
          const p=this._ll2xy(d.lat,d.lon,cx,cy,r,this.rotation,tilt);
          if(p.v){
            const b=p.d*0.6+0.4;
            ctx.fillStyle='rgba(0,160,210,'+(b*0.3)+')';
            ctx.fillRect(p.x-0.7,p.y-0.7,1.4,1.4);
          }
        });
      }
      // China highlighted in gold (fallback)
      if(this._chinaDots){
        this._chinaDots.forEach(d=>{
          const p=this._ll2xy(d.lat,d.lon,cx,cy,r,this.rotation,tilt);
          if(p.v){
            const b=p.d*0.5+0.5;
            ctx.fillStyle='rgba(255,200,60,'+(b*0.55)+')';
            ctx.fillRect(p.x-0.9,p.y-0.9,1.8,1.8);
          }
        });
      }
    }
    // Grid lines (very subtle)
    ctx.strokeStyle='rgba(0,212,255,0.04)';ctx.lineWidth=0.5;
    for(let lat=-60;lat<=60;lat+=15)this._drawLat(ctx,cx,cy,r,lat,tilt);
    for(let lon=0;lon<360;lon+=20)this._drawLon(ctx,cx,cy,r,lon,tilt);
    // Equator
    ctx.strokeStyle='rgba(0,212,255,0.08)';ctx.lineWidth=0.8;
    this._drawLat(ctx,cx,cy,r,0,tilt);
    // Trade routes (Belt & Road, flowing dashed lines)
    this._drawTradeRoutes(ctx,cx,cy,r,tilt);
    // Protection arcs from Beijing to overseas interests
    this._drawProtectLines(ctx,cx,cy,r,tilt);
    // Beijing origin marker
    const bj=this._ll2xy(this.BEIJING.lat,this.BEIJING.lon,cx,cy,r,this.rotation,tilt);
    if(bj.v){
      const t=Date.now();
      const ps=Math.sin(t/600)*0.5+0.5;
      ctx.beginPath();ctx.arc(bj.x,bj.y,8+ps*6,0,Math.PI*2);
      ctx.strokeStyle='rgba(255,200,60,'+(0.5*ps)+')';ctx.lineWidth=2;ctx.stroke();
      ctx.beginPath();ctx.arc(bj.x,bj.y,14+ps*12,0,Math.PI*2);
      ctx.strokeStyle='rgba(255,200,60,'+(0.2*ps)+')';ctx.lineWidth=1;ctx.stroke();
      ctx.beginPath();ctx.arc(bj.x,bj.y,4,0,Math.PI*2);
      ctx.fillStyle='rgba(255,220,100,1)';ctx.fill();
      ctx.beginPath();ctx.arc(bj.x,bj.y,6,0,Math.PI*2);
      ctx.fillStyle='rgba(255,200,60,0.3)';ctx.fill();
      ctx.font='bold 10px "Microsoft YaHei",sans-serif';
      ctx.fillStyle='rgba(255,220,100,0.9)';
      ctx.fillText('★ 北京',bj.x+8,bj.y-4);
    }
    // Country risk dots with pulse
    const t=Date.now();
    COUNTRIES.forEach(c=>{
      if(c.name==='中国')return;
      const p=this._ll2xy(c.lat,c.lon,cx,cy,r,this.rotation,tilt);
      if(!p.v)return;
      const risk=calcOverall(c.scores);
      const ents=getEntsInCountry(c.name).length;
      const sz=2+Math.min(ents*0.3,2.5)+(risk/10)*2.5;
      const a=p.d;
      let col=risk>=8?[255,51,85]:risk>=6?[255,136,0]:risk>=4?[255,204,0]:[0,255,159];
      ctx.beginPath();ctx.arc(p.x,p.y,sz,0,Math.PI*2);
      ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(a*0.95)+')';ctx.fill();
      ctx.beginPath();ctx.arc(p.x,p.y,sz+1.5,0,Math.PI*2);
      ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(a*0.2)+')';ctx.fill();
      if(risk>=7){
        const ps=Math.sin(t/400+c.lon)*0.5+0.5;
        ctx.beginPath();ctx.arc(p.x,p.y,sz+3+ps*8,0,Math.PI*2);
        ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(0.35*ps*a)+')';ctx.lineWidth=1.5;ctx.stroke();
        ctx.beginPath();ctx.arc(p.x,p.y,sz+6+ps*14,0,Math.PI*2);
        ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(0.12*ps*a)+')';ctx.lineWidth=0.8;ctx.stroke();
      }
      if(risk>=7&&p.d>0.35){
        ctx.font='bold 9px "Microsoft YaHei",sans-serif';
        ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(a*0.7)+')';
        ctx.fillText(c.name,p.x+sz+3,p.y+2);
      }
    });
    // Chokepoint diamond markers
    this._chokepoints.forEach(cp=>{
      const p=this._ll2xy(cp.lat,cp.lon,cx,cy,r,this.rotation,tilt);
      if(!p.v)return;
      ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.PI/4);
      ctx.strokeStyle='rgba(255,170,0,'+(p.d*0.8)+')';ctx.lineWidth=1.5;
      ctx.strokeRect(-3,-3,6,6);
      ctx.fillStyle='rgba(255,170,0,'+(p.d*0.3)+')';
      ctx.fillRect(-3,-3,6,6);
      ctx.restore();
    });
    // Radar sweep
    ctx.save();ctx.translate(cx,cy);
    const sa=this._scanAngle;
    if(ctx.createConicGradient){
      const grad=ctx.createConicGradient(sa,0,0);
      grad.addColorStop(0,'rgba(0,212,255,0.15)');
      grad.addColorStop(0.05,'rgba(0,212,255,0)');
      grad.addColorStop(1,'rgba(0,212,255,0)');
      ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);
      ctx.fillStyle=grad;ctx.fill();
    }else{
      ctx.beginPath();ctx.moveTo(0,0);
      ctx.arc(0,0,r,sa-0.25,sa);ctx.closePath();
      const lg=ctx.createLinearGradient(0,0,r*Math.cos(sa),r*Math.sin(sa));
      lg.addColorStop(0,'rgba(0,212,255,0)');lg.addColorStop(1,'rgba(0,212,255,0.12)');
      ctx.fillStyle=lg;ctx.fill();
    }
    ctx.restore();
    // Sphere outline
    ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);
    ctx.strokeStyle='rgba(0,212,255,0.2)';ctx.lineWidth=1;ctx.stroke();
    ctx.beginPath();ctx.arc(cx,cy,r+3,0,Math.PI*2);
    ctx.strokeStyle='rgba(0,212,255,0.06)';ctx.lineWidth=0.5;ctx.stroke();
    // Orbital ring (tilted ellipse)
    ctx.save();ctx.translate(cx,cy);
    ctx.rotate(this._time*0.0003);
    ctx.strokeStyle='rgba(0,212,255,0.08)';ctx.lineWidth=0.5;
    ctx.beginPath();ctx.ellipse(0,0,r*1.18,r*0.32,0,0,Math.PI*2);ctx.stroke();
    ctx.strokeStyle='rgba(0,212,255,0.05)';
    ctx.beginPath();ctx.ellipse(0,0,r*1.28,r*0.45,Math.PI/6,0,Math.PI*2);ctx.stroke();
    ctx.beginPath();ctx.ellipse(0,0,r*1.35,r*0.2,-Math.PI/5,0,Math.PI*2);ctx.stroke();
    // Orbiting satellites
    for(var si=0;si<3;si++){
      var sAng=this._time*0.008*(si+1)*0.5+si*Math.PI*0.7;
      var orbR=r*(1.18+si*0.05);
      var orbY=r*(0.32+si*0.06);
      var sx=Math.cos(sAng)*orbR;
      var sy=Math.sin(sAng)*orbY;
      var sFront=sy<0;
      ctx.fillStyle=sFront?'rgba(0,255,159,0.9)':'rgba(0,255,159,0.3)';
      ctx.beginPath();ctx.arc(sx,sy,sFront?2.5:1.5,0,Math.PI*2);ctx.fill();
      if(sFront){
        ctx.beginPath();ctx.arc(sx,sy,5,0,Math.PI*2);
        ctx.strokeStyle='rgba(0,255,159,0.2)';ctx.lineWidth=1;ctx.stroke();
        ctx.font='8px "Courier New",monospace';
        ctx.fillStyle='rgba(0,255,159,0.6)';
        ctx.fillText('SAT-'+(si+1),sx+6,sy+2);
      }
    }
    ctx.restore();
    // Wide-orbit escort craft (front pass, above globe)
    this._drawEscorts(ctx,cx,cy,r);
    // Coordinate tick marks around globe
    ctx.save();ctx.translate(cx,cy);
    for(var a=0;a<360;a+=30){
      var rad=a*Math.PI/180;
      var tx1=Math.cos(rad)*(r+6),ty1=Math.sin(rad)*(r+6);
      var tx2=Math.cos(rad)*(r+10),ty2=Math.sin(rad)*(r+10);
      ctx.strokeStyle='rgba(0,212,255,0.15)';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(tx1,ty1);ctx.lineTo(tx2,ty2);ctx.stroke();
    }
    ctx.restore();
    // HUD time
    const te=document.getElementById('globe-hud-time');
    if(te)te.textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false});
  },
  _drawBackdrop(ctx,w,h,cx,cy,r){
    const t=this._time;
    // 1) Drifting data constellation (fills side whitespace, very low alpha)
    if(!this._nodes){
      this._nodes=[];
      const n=Math.max(50,Math.min(100,Math.round(w/16)));
      for(let i=0;i<n;i++)this._nodes.push({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-0.5)*0.18,vy:(Math.random()-0.5)*0.18,s:Math.random()<0.2?1.8:1.1});
    }
    const nodes=this._nodes,LD=110;
    ctx.lineWidth=0.5;
    for(let i=0;i<nodes.length;i++){
      const a=nodes[i];
      a.x+=a.vx;a.y+=a.vy;
      if(a.x<-10)a.x=w+10;if(a.x>w+10)a.x=-10;
      if(a.y<-10)a.y=h+10;if(a.y>h+10)a.y=-10;
      for(let j=i+1;j<nodes.length;j++){
        const b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy;
        if(d2<LD*LD){
          const al=(1-Math.sqrt(d2)/LD)*0.12;
          ctx.strokeStyle='rgba(91,155,255,'+al+')';
          ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();
        }
      }
      ctx.fillStyle='rgba(120,175,255,0.40)';
      ctx.fillRect(a.x,a.y,a.s,a.s);
    }
    // 1b) Soft side light columns (reduce dark edge feeling)
    const sg=ctx.createLinearGradient(0,0,120,0);
    sg.addColorStop(0,'rgba(91,155,255,0.08)');sg.addColorStop(0.7,'rgba(91,155,255,0.02)');sg.addColorStop(1,'rgba(91,155,255,0)');
    ctx.fillStyle=sg;ctx.fillRect(0,0,120,h);
    const sg2=ctx.createLinearGradient(w-120,0,w,0);
    sg2.addColorStop(0,'rgba(91,155,255,0)');sg2.addColorStop(0.3,'rgba(91,155,255,0.02)');sg2.addColorStop(1,'rgba(91,155,255,0.08)');
    ctx.fillStyle=sg2;ctx.fillRect(w-120,0,120,h);
    // 2) Wide escort orbits behind globe (reach into left/right whitespace)
    this._wideOrbits=[
      {rx:Math.min(w*0.40,r*2.7),ry:r*0.60,rot:-0.14,speed:0.0035,ph:0},
      {rx:Math.min(w*0.33,r*2.2),ry:r*0.88,rot:0.20,speed:-0.0026,ph:2.1},
      {rx:Math.min(w*0.45,r*3.1),ry:r*0.38,rot:0.04,speed:0.0020,ph:4.2}
    ];
    ctx.save();ctx.translate(cx,cy);
    this._wideOrbits.forEach(o=>{
      ctx.save();ctx.rotate(o.rot);
      ctx.setLineDash([3,7]);
      ctx.strokeStyle='rgba(91,155,255,0.15)';ctx.lineWidth=0.8;
      ctx.beginPath();ctx.ellipse(0,0,o.rx,o.ry,0,0,Math.PI*2);ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    });
    ctx.restore();
    // 3) Rotating tech rings hugging the globe
    ctx.save();ctx.translate(cx,cy);
    ctx.save();ctx.rotate(t*0.0022);
    ctx.setLineDash([2,8]);
    ctx.strokeStyle='rgba(0,212,255,0.14)';ctx.lineWidth=1;
    ctx.beginPath();ctx.arc(0,0,r*1.09,0,Math.PI*2);ctx.stroke();
    ctx.restore();
    ctx.save();ctx.rotate(-t*0.0013);
    ctx.setLineDash([14,18]);
    ctx.strokeStyle='rgba(91,155,255,0.10)';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,0,r*1.24,0,Math.PI*2);ctx.stroke();
    ctx.restore();
    ctx.restore();
    // 4) Full-width horizontal scan beam (slow sweep, very faint)
    const beamY=((t*0.5)%(h+200))-100;
    const bg2=ctx.createLinearGradient(0,beamY-30,0,beamY+30);
    bg2.addColorStop(0,'rgba(91,155,255,0)');
    bg2.addColorStop(0.5,'rgba(91,155,255,0.07)');
    bg2.addColorStop(1,'rgba(91,155,255,0)');
    ctx.fillStyle=bg2;ctx.fillRect(0,beamY-30,w,60);
    ctx.strokeStyle='rgba(120,180,255,0.14)';ctx.lineWidth=0.6;
    ctx.beginPath();ctx.moveTo(0,beamY);ctx.lineTo(w,beamY);ctx.stroke();
    // 5) Edge spectrum walls (mid-band left/right)
    this._drawSpectrumWall(ctx,6,cy,1,t);
    this._drawSpectrumWall(ctx,w-6,cy,-1,t);
  },
  _drawSpectrumWall(ctx,x,cy,dir,t){
    const bars=30,gap=8;
    const y0=cy-(bars*gap)/2;
    for(let i=0;i<bars;i++){
      const lv=Math.abs(Math.sin(i*0.9+t*0.035)+Math.sin(i*0.37-t*0.021))*0.5;
      const len=6+lv*44;
      const y=y0+i*gap;
      const al=0.06+lv*0.16;
      ctx.fillStyle='rgba(91,155,255,'+al+')';
      if(dir>0)ctx.fillRect(x,y,len,2);else ctx.fillRect(x-len,y,len,2);
      if(lv>0.82){
        ctx.fillStyle='rgba(160,205,255,'+(al+0.18)+')';
        if(dir>0)ctx.fillRect(x+len-2,y,2,2);else ctx.fillRect(x-len,y,2,2);
      }
    }
  },
  _drawEscorts(ctx,cx,cy,r){
    if(!this._wideOrbits)return;
    const t=this._time;
    ctx.save();ctx.translate(cx,cy);
    this._wideOrbits.forEach(o=>{
      ctx.save();ctx.rotate(o.rot);
      const dirS=o.speed>=0?1:-1;
      for(let k=0;k<2;k++){
        const ang=t*o.speed+o.ph+k*Math.PI;
        const ex=Math.cos(ang)*o.rx,ey=Math.sin(ang)*o.ry;
        const front=ey>0;
        // Faint contrail along orbit behind aircraft (line segments, very low alpha)
        ctx.strokeStyle='rgba(140,195,255,'+(front?0.18:0.08)+')';
        ctx.lineWidth=0.5;
        ctx.beginPath();
        let first=true;
        for(let s=1;s<=10;s++){
          const a2=ang-s*0.026*dirS;
          const tx2=Math.cos(a2)*o.rx,ty2=Math.sin(a2)*o.ry;
          if(ty2<=0)continue;
          if(first){ctx.moveTo(tx2,ty2);first=false;}else ctx.lineTo(tx2,ty2);
        }
        ctx.stroke();
        // Tangent heading: derivative of (rx cos θ, ry sin θ) = (-rx sin θ, ry cos θ)
        const tx=-o.rx*Math.sin(ang),ty=o.ry*Math.cos(ang);
        const head=Math.atan2(ty,tx);
        const al=front?0.62:0.18;
        const sc=front?1.1:0.8;
        ctx.save();
        ctx.translate(ex,ey);
        ctx.rotate(head);
        // Soft glow under aircraft
        const glow=ctx.createRadialGradient(0,0,1,0,0,7*sc);
        glow.addColorStop(0,'rgba(140,195,255,'+(front?0.25:0.10)+')');
        glow.addColorStop(1,'rgba(140,195,255,0)');
        ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,7*sc,0,Math.PI*2);ctx.fill();
        // Minimal aircraft silhouette (delta fighter, facing forward)
        ctx.beginPath();
        ctx.moveTo(0,5*sc);
        ctx.lineTo(-4*sc,-2*sc);
        ctx.lineTo(-1*sc,-3*sc);
        ctx.lineTo(1*sc,-3*sc);
        ctx.lineTo(4*sc,-2*sc);
        ctx.closePath();
        ctx.fillStyle='rgba(140,195,255,'+al+')';
        ctx.fill();
        ctx.strokeStyle='rgba(160,210,255,'+(al*0.8)+')';
        ctx.lineWidth=0.5;
        ctx.stroke();
        ctx.restore();
      }
      ctx.restore();
    });
    ctx.restore();
  },
  _drawProtectLines(ctx,cx,cy,r,tilt){
    if(!this._protectLines)return;
    this._protectLines.forEach(line=>{
      const p1=this._ll2xy(line.from.lat,line.from.lon,cx,cy,r,this.rotation,tilt);
      const p2=this._ll2xy(line.to.lat,line.to.lon,cx,cy,r,this.rotation,tilt);
      if(!p1.v&&!p2.v)return;
      const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;
      const dx=p2.x-p1.x,dy=p2.y-p1.y;
      const dist=Math.sqrt(dx*dx+dy*dy);
      const elev=Math.min(dist*0.35,r*0.35);
      const cx2=mx,cy2=my-elev;
      const col=line.risk>=8?[255,51,85]:line.risk>=6?[255,136,0]:line.risk>=4?[255,204,0]:[0,255,159];
      // Faint full arc
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);
      ctx.quadraticCurveTo(cx2,cy2,p2.x,p2.y);
      ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+',0.06)';ctx.lineWidth=0.6;ctx.stroke();
      // Active trail
      const pr=line.progress;const segs=20;
      for(let i=0;i<segs;i++){
        const t0=i/segs,t1=(i+1)/segs;
        if(t0>pr)break;
        const tEnd=Math.min(t1,pr);
        const x0=(1-t0)*(1-t0)*p1.x+2*(1-t0)*t0*cx2+t0*t0*p2.x;
        const y0=(1-t0)*(1-t0)*p1.y+2*(1-t0)*t0*cy2+t0*t0*p2.y;
        const x1=(1-tEnd)*(1-tEnd)*p1.x+2*(1-tEnd)*tEnd*cx2+tEnd*tEnd*p2.x;
        const y1=(1-tEnd)*(1-tEnd)*p1.y+2*(1-tEnd)*tEnd*cy2+tEnd*tEnd*p2.y;
        const alpha=(1-t0/pr)*0.5;
        ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1,y1);
        ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+alpha+')';ctx.lineWidth=1.2;ctx.stroke();
      }
      // Head particle
      if(pr>0.01&&pr<0.99){
        const px=(1-pr)*(1-pr)*p1.x+2*(1-pr)*pr*cx2+pr*pr*p2.x;
        const py=(1-pr)*(1-pr)*p1.y+2*(1-pr)*pr*cy2+pr*pr*p2.y;
        ctx.beginPath();ctx.arc(px,py,2.5,0,Math.PI*2);
        ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+',0.9)';ctx.fill();
        ctx.beginPath();ctx.arc(px,py,5,0,Math.PI*2);
        ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+',0.2)';ctx.fill();
      }
    });
  },
  _drawTradeRoutes(ctx,cx,cy,r,tilt){
    if(!this._tradeRoutes)return;
    this._tradeRoutes.forEach(route=>{
      const p1=this._ll2xy(route.from.lat,route.from.lon,cx,cy,r,this.rotation,tilt);
      const p2=this._ll2xy(route.to.lat,route.to.lon,cx,cy,r,this.rotation,tilt);
      if(!p1.v||!p2.v)return;
      const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;
      const dx=p2.x-p1.x,dy=p2.y-p1.y;
      const dist=Math.sqrt(dx*dx+dy*dy);
      const elev=Math.min(dist*0.45,r*0.45);
      const cx2=mx,cy2=my-elev;
      ctx.setLineDash([4,4]);
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);
      ctx.quadraticCurveTo(cx2,cy2,p2.x,p2.y);
      ctx.strokeStyle='rgba(0,212,255,0.1)';ctx.lineWidth=0.8;ctx.stroke();
      ctx.setLineDash([]);
      const pr=route.progress;
      const px=(1-pr)*(1-pr)*p1.x+2*(1-pr)*pr*cx2+pr*pr*p2.x;
      const py=(1-pr)*(1-pr)*p1.y+2*(1-pr)*pr*cy2+pr*pr*p2.y;
      ctx.beginPath();ctx.arc(px,py,2,0,Math.PI*2);
      ctx.fillStyle='rgba(0,212,255,0.7)';ctx.fill();
      ctx.beginPath();ctx.arc(px,py,4,0,Math.PI*2);
      ctx.fillStyle='rgba(0,212,255,0.15)';ctx.fill();
    });
  },
  _drawLat(ctx,cx,cy,r,lat,tilt){
    ctx.beginPath();let s=false;
    for(let lon=0;lon<=360;lon+=2){
      const p=this._ll2xy(lat,lon,cx,cy,r,this.rotation,tilt);
      if(p.v){if(!s){ctx.moveTo(p.x,p.y);s=true;}else ctx.lineTo(p.x,p.y);}
      else s=false;
    }
    ctx.stroke();
  },
  _drawLon(ctx,cx,cy,r,lon,tilt){
    ctx.beginPath();let s=false;
    for(let lat=-85;lat<=85;lat+=2){
      const p=this._ll2xy(lat,lon,cx,cy,r,this.rotation,tilt);
      if(p.v){if(!s){ctx.moveTo(p.x,p.y);s=true;}else ctx.lineTo(p.x,p.y);}
      else s=false;
    }
    ctx.stroke();
  }
};

/* ============================================================
 * FLATMAP — 平面世界地图模式（COSRI 对标 P0-1，2026-08-29）
 * 等距圆柱投影：复用 GLOBE 的陆地点阵数据换投影渲染；
 * 国家风险四色标记 + 高危国标签 + 咽喉点 + 北京原点；
 * 点击国家 → COUNTRY_DRAWER 联动侧抽屉（P0-2）。
 * ============================================================ */
const FLATMAP={
  canvas:null,ctx:null,_hover:null,_bound:false,
  PAD:{l:34,r:16,t:26,b:34}, /* 留出经纬度刻度 */
  init(){
    this.canvas=document.getElementById('flatmap-canvas');
    if(!this.canvas)return;
    this.ctx=this.canvas.getContext('2d');
    const gc=document.getElementById('globe-canvas');
    if(gc&&this.canvas.width!==gc.width){this.canvas.width=gc.width;}
    this.canvas.height=500;
    if(!GLOBE._landDots)GLOBE._genLandDots();
    if(!this._bound){
      this._bound=true;
      this.canvas.addEventListener('mousemove',e=>{
        const hit=this._hit(e);
        this._hover=hit;
        this.canvas.style.cursor=hit?'pointer':'crosshair';
        if(hit){
          const el=document.getElementById('globe-hud-coord');
          if(el)el.textContent=hit+' · 点击查看国别详情';
        }
      });
      this.canvas.addEventListener('mouseleave',()=>{this._hover=null;});
      this.canvas.addEventListener('click',e=>{
        const hit=this._hit(e);
        if(hit&&typeof COUNTRY_DRAWER!=='undefined')COUNTRY_DRAWER.open(hit);
      });
      window.addEventListener('resize',()=>{if(this.canvas&&gc){this.canvas.width=gc.parentElement.clientWidth;this.canvas.height=500;}});
    }
  },
  _proj(lat,lon){
    const w=this.canvas.width,h=this.canvas.height,P=this.PAD;
    const x=P.l+((lon+180)/360)*(w-P.l-P.r);
    const y=P.t+((90-lat)/180)*(h-P.t-P.b);
    return{x,y};
  },
  _hit(e){
    if(!this.canvas)return null;
    const rect=this.canvas.getBoundingClientRect();
    const mx=(e.clientX-rect.left)*(this.canvas.width/rect.width);
    const my=(e.clientY-rect.top)*(this.canvas.height/rect.height);
    let best=null,bestD=15;
    COUNTRIES.forEach(c=>{
      if(c.name==='中国')return;
      const p=this._proj(c.lat,c.lon);
      const d=Math.hypot(p.x-mx,p.y-my);
      if(d<bestD){bestD=d;best=c.name;}
    });
    return best;
  },
  _riskCol(risk){
    return risk>=8?[255,51,85]:risk>=6?[255,136,0]:risk>=4?[255,204,0]:[0,255,159];
  },
  draw(){
    if(!this.canvas||!this.ctx)return;
    const ctx=this.ctx,w=this.canvas.width,h=this.canvas.height,P=this.PAD;
    const t=Date.now();
    /* 深空背景（与地球模式同源） */
    const bg=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)*0.7);
    bg.addColorStop(0,'#0a1428');bg.addColorStop(0.5,'#070b14');bg.addColorStop(1,'#030508');
    ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
    /* 星点 */
    if(!GLOBE._stars){GLOBE._stars=[];for(let i=0;i<200;i++)GLOBE._stars.push({x:Math.random()*w,y:Math.random()*h,s:Math.random()*1.8+0.2,p:Math.random()*Math.PI*2,sp:0.015+Math.random()*0.04});}
    GLOBE._stars.forEach(s=>{
      const tw=Math.sin(GLOBE._time*s.sp+s.p)*0.3+0.7;
      ctx.fillStyle='rgba('+(s.s>1.2?'180,220,255':'100,140,180')+','+(tw*0.5)+')';
      ctx.fillRect(s.x,s.y,s.s,s.s);
    });
    /* 地图投影区边框 */
    ctx.strokeStyle='rgba(0,212,255,0.25)';ctx.lineWidth=1;
    ctx.strokeRect(P.l,P.t,w-P.l-P.r,h-P.t-P.b);
    /* 网格经纬线 */
    ctx.strokeStyle='rgba(0,212,255,0.06)';ctx.lineWidth=0.5;
    for(let lon=-180;lon<=180;lon+=30){
      const p1=this._proj(85,lon),p2=this._proj(-85,lon);
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();
    }
    for(let lat=-60;lat<=80;lat+=20){
      const p1=this._proj(lat,-180),p2=this._proj(lat,180);
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();
    }
    /* 赤道高亮 */
    ctx.strokeStyle='rgba(0,212,255,0.14)';ctx.lineWidth=0.8;
    const e1=this._proj(0,-180),e2=this._proj(0,180);
    ctx.beginPath();ctx.moveTo(e1.x,e1.y);ctx.lineTo(e2.x,e2.y);ctx.stroke();
    /* 经纬度刻度文字 */
    ctx.font='8px "Courier New",monospace';ctx.fillStyle='rgba(0,212,255,0.35)';
    [-120,-60,0,60,120].forEach(lon=>{const p=this._proj(85,lon);ctx.fillText((lon===0?'0°':(lon>0?lon+'E':(-lon)+'W')),p.x-8,P.t-4);});
    [60,30,0,-30].forEach(lat=>{const p=this._proj(lat,-180);ctx.fillText(Math.abs(lat)+'°'+(lat>=0?'N':'S'),6,p.y+3);});
    /* 真实地理底图层：大陆轮廓 + 国界 + 中国金色高亮（失败回退点阵） */
    if(GLOBE._geo){
      const geo=GLOBE._geo;
      /* 陆块多边形 */
      ctx.beginPath();
      const polys=geo.land.geometry.type==='Polygon'?[geo.land.geometry.coordinates]:geo.land.geometry.coordinates;
      polys.forEach(poly=>poly.forEach(ring=>{
        ring.forEach((v,i)=>{
          const p=this._proj(v[1],v[0]);
          if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);
        });
        ctx.closePath();
      }));
      ctx.fillStyle='rgba(16,52,86,0.9)';
      ctx.fill();
      ctx.strokeStyle='rgba(0,212,255,0.35)';
      ctx.lineWidth=0.6;
      ctx.stroke();
      /* 国界线 */
      ctx.beginPath();
      geo.borders.coordinates.forEach(line=>{
        line.forEach((v,i)=>{
          const p=this._proj(v[1],v[0]);
          if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);
        });
      });
      ctx.strokeStyle='rgba(0,212,255,0.14)';
      ctx.lineWidth=0.4;
      ctx.stroke();
      /* 中国（含台湾）金色高亮 */
      ctx.beginPath();
      geo.chinaPolys.forEach(poly=>poly.forEach(ring=>{
        ring.forEach((v,i)=>{
          const p=this._proj(v[1],v[0]);
          if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);
        });
        ctx.closePath();
      }));
      ctx.fillStyle='rgba(255,200,60,0.25)';
      ctx.fill();
      ctx.strokeStyle='rgba(255,200,60,0.65)';
      ctx.lineWidth=0.8;
      ctx.stroke();
    }else{
      /* 陆地点阵回退（等距圆柱投影） */
      if(GLOBE._landDots)GLOBE._landDots.forEach(d=>{
        const p=this._proj(d.lat,d.lon);
        ctx.fillStyle='rgba(0,160,210,0.22)';
        ctx.fillRect(p.x-0.7,p.y-0.7,1.4,1.4);
      });
      if(GLOBE._chinaDots)GLOBE._chinaDots.forEach(d=>{
        const p=this._proj(d.lat,d.lon);
        ctx.fillStyle='rgba(255,200,60,0.4)';
        ctx.fillRect(p.x-0.8,p.y-0.8,1.6,1.6);
      });
    }
    /* 贸易航线（北京→枢纽，直线渐变） */
    ctx.setLineDash([4,4]);ctx.lineWidth=1;
    GLOBE._chokepoints.forEach(cp=>{
      const bj=this._proj(GLOBE.BEIJING.lat,GLOBE.BEIJING.lon);
      const p=this._proj(cp.lat,cp.lon);
      ctx.strokeStyle='rgba(0,212,255,0.12)';
      ctx.beginPath();ctx.moveTo(bj.x,bj.y);ctx.lineTo(p.x,p.y);ctx.stroke();
    });
    ctx.setLineDash([]);
    /* 国家风险标记 */
    COUNTRIES.forEach(c=>{
      if(c.name==='中国')return;
      const p=this._proj(c.lat,c.lon);
      const risk=calcOverall(c.scores);
      const ents=getEntsInCountry(c.name).length;
      const col=this._riskCol(risk);
      const sz=2.5+Math.min(ents*0.35,2.5)+(risk/10)*3;
      const hov=this._hover===c.name;
      /* 有 24h 预警的国家加脉冲环 */
      var has24=false;
      try{has24=(ALERTS||[]).some(function(a){return a.country===c.name&&a.status!=='resolved'&&SITUATION._freshItem(a,24);});}catch(e){}
      if(risk>=7||has24){
        const ps=Math.sin(t/400+c.lon)*0.5+0.5;
        ctx.beginPath();ctx.arc(p.x,p.y,sz+3+ps*7,0,Math.PI*2);
        ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(0.35*ps)+')';ctx.lineWidth=1.5;ctx.stroke();
        ctx.beginPath();ctx.arc(p.x,p.y,sz+6+ps*12,0,Math.PI*2);
        ctx.strokeStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(0.12*ps)+')';ctx.lineWidth=0.8;ctx.stroke();
      }
      if(has24){
        ctx.beginPath();ctx.arc(p.x,p.y,sz+2,0,Math.PI*2);
        ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+',0.25)';ctx.fill();
      }
      ctx.beginPath();ctx.arc(p.x,p.y,hov?sz+2:sz,0,Math.PI*2);
      ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+','+(hov?1:0.9)+')';ctx.fill();
      ctx.beginPath();ctx.arc(p.x,p.y,sz+1.5,0,Math.PI*2);
      ctx.fillStyle='rgba('+col[0]+','+col[1]+','+col[2]+',0.18)';ctx.fill();
      /* 高危/悬停 国家名标签 */
      if(risk>=6||hov){
        ctx.font='bold '+(hov?'10px':'9px')+' "Microsoft YaHei",sans-serif';
        ctx.fillStyle=hov?'rgba(255,255,255,0.95)':'rgba('+col[0]+','+col[1]+','+col[2]+',0.75)';
        ctx.fillText(c.name,p.x+sz+3,p.y+3);
      }
    });
    /* 海上咽喉点（菱形） */
    GLOBE._chokepoints.forEach(cp=>{
      const p=this._proj(cp.lat,cp.lon);
      ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.PI/4);
      ctx.strokeStyle='rgba(255,170,0,0.85)';ctx.lineWidth=1.5;
      ctx.strokeRect(-3.5,-3.5,7,7);
      ctx.fillStyle='rgba(255,170,0,0.3)';
      ctx.fillRect(-3.5,-3.5,7,7);
      ctx.restore();
      ctx.font='9px "Microsoft YaHei",sans-serif';ctx.fillStyle='rgba(255,170,0,0.7)';
      ctx.fillText(cp.name,p.x+7,p.y-4);
    });
    /* 北京原点 */
    const bj=this._proj(GLOBE.BEIJING.lat,GLOBE.BEIJING.lon);
    const ps2=Math.sin(t/600)*0.5+0.5;
    ctx.beginPath();ctx.arc(bj.x,bj.y,4,0,Math.PI*2);ctx.fillStyle='rgba(255,220,100,1)';ctx.fill();
    ctx.beginPath();ctx.arc(bj.x,bj.y,8+ps2*6,0,Math.PI*2);ctx.strokeStyle='rgba(255,200,60,'+(0.5*ps2)+')';ctx.lineWidth=1.5;ctx.stroke();
    ctx.font='bold 10px "Microsoft YaHei",sans-serif';ctx.fillStyle='rgba(255,220,100,0.9)';
    ctx.fillText('★ 北京',bj.x+9,bj.y+3);
    /* 模式标注 */
    ctx.font='10px "Microsoft YaHei",sans-serif';ctx.fillStyle='rgba(0,212,255,0.5)';
    ctx.fillText('🗺️ 平面地图模式 · 点击国家查看联动详情',P.l,h-10);
    /* HUD 时间 */
    const te=document.getElementById('globe-hud-time');
    if(te)te.textContent=new Date().toLocaleTimeString('zh-CN',{hour12:false});
  }
};

/* ============================================================
 * COUNTRY_DRAWER — 国家联动侧抽屉（COSRI 对标 P0-2，2026-08-29）
 * 点地图国家 → 右侧抽屉：①COSI 风格指数卡(综合风险+7日sparkline+四维)
 * ②最近24h该国预警5条 ③该国中资项目清单 ④在档人员机构数量。
 * 数据：客户端 COUNTRIES/ALERTS/ENTERPRISES 实时计算 + /api/cosri/<国> 增强。
 * ============================================================ */
const COUNTRY_DRAWER={
  _open:null,_escBound:false,
  open(name){
    var self=this;
    this._open=name;
    var d=document.getElementById('country-drawer');
    var ov=document.getElementById('country-drawer-overlay');
    if(!d||!ov)return;
    d.innerHTML='<div class="cd-body" style="display:flex;align-items:center;justify-content:center;color:var(--text3);padding:40px 0;font-size:12px">加载 '+name+' 国别数据…</div>';
    d.classList.add('open');ov.classList.add('show');
    if(!this._escBound){
      this._escBound=true;
      document.addEventListener('keydown',function(e){if(e.key==='Escape')self.close();});
    }
    this._render(name);
  },
  close(){
    this._open=null;
    var d=document.getElementById('country-drawer');
    var ov=document.getElementById('country-drawer-overlay');
    if(d)d.classList.remove('open');
    if(ov)ov.classList.remove('show');
  },
  /* 最近 N 天每日该国预警量（sparkline 数据源） */
  _dailyCounts(name,days){
    var buckets=[],now=new Date();
    for(var i=days-1;i>=0;i--){
      var day=new Date(now.getTime()-i*86400000);
      var key=day.getFullYear()+'-'+String(day.getMonth()+1).padStart(2,'0')+'-'+String(day.getDate()).padStart(2,'0');
      buckets.push({key:key,n:0,dd:String(day.getMonth()+1).padStart(2,'0')+'/'+String(day.getDate()).padStart(2,'0')});
    }
    var idx={};buckets.forEach(function(b){idx[b.key]=b;});
    (ALERTS||[]).forEach(function(a){
      if(a.country!==name)return;
      var t=String(a.time||'').replace(' ','T');
      var d2=null;try{d2=new Date(t);}catch(e){}
      if(!d2||isNaN(d2.getTime()))return;
      var key=d2.getFullYear()+'-'+String(d2.getMonth()+1).padStart(2,'0')+'-'+String(d2.getDate()).padStart(2,'0');
      if(idx[key])idx[key].n++;
    });
    return buckets;
  },
  _spark(series,w,h,color){
    var max=Math.max.apply(null,series.map(function(s){return s.n;}).concat([1]));
    var step=series.length>1?w/(series.length-1):w;
    var pts=series.map(function(s,i){
      var y=h-3-(s.n/max)*(h-8);
      return (i*step).toFixed(1)+','+y.toFixed(1);
    }).join(' ');
    var dots=series.map(function(s,i){
      var y=h-3-(s.n/max)*(h-8);
      return '<circle cx="'+(i*step).toFixed(1)+'" cy="'+y.toFixed(1)+'" r="1.8" fill="'+color+'"><title>'+s.dd+'：'+s.n+' 条</title></circle>';
    }).join('');
    return '<svg width="'+w+'" height="'+h+'" style="display:block">'+
      '<polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.5" stroke-linejoin="round"/>'+
      '<polyline points="0,'+h+' '+pts+' '+w+','+h+'" fill="'+color+'18" stroke="none"/>'+dots+'</svg>';
  },
  _render(name){
    var self=this;
    var c=COUNTRIES.find(function(x){return x.name===name;});
    var d=document.getElementById('country-drawer');
    if(!d)return;
    /* --- 客户端即时数据 --- */
    var ov=c?calcOverall(c.scores):null;
    var lv=ov!==null?getLevel(ov):null;
    var ents=getEntsInCountry(name);
    var pers=ents.reduce(function(s,e){return s+(e.personnel||0);},0);
    var inv=ents.reduce(function(s,e){return s+(e.investment||0);},0);
    var alerts24=[];
    try{alerts24=(ALERTS||[]).filter(function(a){return a.country===name&&SITUATION._freshItem(a,24);}).sort(function(a,b){return String(b.time||'').localeCompare(String(a.time||''));});}catch(e){}
    var localProjects=[];
    (ENTERPRISES||[]).forEach(function(e){
      (e.projects||[]).forEach(function(p){if(p.c===name)localProjects.push({name:p.n,ent:e.short,inv:p.inv,pers:p.p});});
    });
    var week=this._dailyCounts(name,7);
    var weekN=week.reduce(function(s,b){return s+b.n;},0);
    var projHtml=localProjects.length?localProjects.map(function(p){
      return '<div style="padding:7px 10px;background:var(--bg2);border-radius:6px;margin-bottom:4px;border-left:3px solid var(--cyan)">'+
        '<div style="font-size:12px;font-weight:700;color:var(--text1)">'+p.name+'</div>'+
        '<div style="font-size:10px;color:var(--text3);margin-top:2px">'+p.ent+' · '+(p.inv?p.inv+'亿$ · ':'')+(p.p?p.p+'人':'')+'</div></div>';
    }).join(''):'<div id="cd-proj-ph" style="padding:8px;font-size:11px;color:var(--text3)">查询中资项目库…</div>';
    var aHtml=alerts24.length?alerts24.slice(0,5).map(function(a){
      var l=ALERT_LV[a.level]||{label:a.level,cls:'b-blue'};
      return '<div style="padding:7px 8px;background:var(--panel2);border-radius:6px;margin-bottom:4px;cursor:pointer;border-left:3px solid '+(a.level==='red'?'var(--red)':a.level==='orange'?'var(--orange)':'var(--yellow)')+'" onclick="navigateTo(\'alerts\');setTimeout(function(){if(typeof AVIEW!==\'undefined\')AVIEW.selectAlert(\''+String(a.id).replace(/[^a-zA-Z0-9_-]/g,'')+'\');},350)">'+
        '<div style="display:flex;gap:5px;align-items:center"><span class="badge '+l.cls+'" style="font-size:8px;padding:0 4px">'+l.label+'</span>'+
        '<span style="flex:1;font-size:11px;font-weight:600;color:var(--text1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+stripTags(_dedupeTitleConcat(a.title_zh||a.title||'')).slice(0,30)+'</span></div>'+
        '<div style="font-size:9px;color:var(--text3);margin-top:2px">🕐 '+String(a.time||'').slice(5,16)+' · '+(a.type||'安全风险')+'</div></div>';
    }).join(''):'<div style="padding:10px;font-size:11px;color:var(--text3);text-align:center">最近 24 小时无该国预警</div>';
    /* --- HTML --- */
    d.innerHTML=
      '<div class="cd-head">'+
        '<div class="flag">'+(c?c.flag:'🌐')+'</div>'+
        '<div><div class="nm">'+name+'</div><div class="sub">'+(c?(c.region+' · '+c.capital):'（系统未建档国，仅实时情报）')+'</div></div>'+
        (lv?'<span class="badge '+lv.cls+'" style="margin-left:8px">'+lv.label+' '+ov.toFixed(1)+'</span>':'')+
        '<div class="cd-close" onclick="COUNTRY_DRAWER.close()">✕</div>'+
      '</div>'+
      '<div class="cd-body">'+
        '<div class="cd-sec-tt">📊 COSI 综合风险指数 <span style="margin-left:auto;font-size:9px;font-weight:400;color:var(--text3)">近7日 '+weekN+' 条预警</span></div>'+
        (ov!==null?
          '<div style="padding:10px 12px;background:linear-gradient(135deg,rgba(0,212,255,0.06),rgba(0,255,159,0.04));border:1px solid rgba(0,212,255,0.2);border-radius:10px;display:flex;gap:12px;align-items:center">'+
            '<div style="text-align:center;flex-shrink:0">'+
              '<div style="font-size:34px;font-weight:900;color:'+lv.color+';line-height:1;font-family:\'Courier New\',monospace">'+ov.toFixed(1)+'</div>'+
              '<div style="font-size:9px;color:var(--text3);margin-top:3px">风险指数 /10</div>'+
            '</div>'+
            '<div style="flex:1;min-width:0">'+
              '<div style="font-size:9px;color:var(--text3);margin-bottom:2px">近 7 日预警趋势</div>'+
              this._spark(week,150,42,lv.color)+
            '</div>'+
          '</div>':
          '<div style="padding:10px;font-size:11px;color:var(--text3)">该国暂无风险评分底数</div>')+
        '<div class="cd-sec-tt">🚨 最近 24 小时预警 ('+alerts24.length+')</div>'+aHtml+
        '<div class="cd-sec-tt">🏗️ 在该国中资项目 ('+localProjects.length+')</div>'+
        '<div id="cd-projects">'+projHtml+'</div>'+
        '<div class="cd-sec-tt">👥 在档企业 / 人员机构</div>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">'+
          '<div style="padding:8px;background:var(--bg2);border-radius:8px;text-align:center"><div style="font-size:20px;font-weight:800;color:var(--cyan)">'+ents.length+'</div><div style="font-size:9px;color:var(--text3)">在档企业</div></div>'+
          '<div style="padding:8px;background:var(--bg2);border-radius:8px;text-align:center"><div style="font-size:20px;font-weight:800;color:var(--orange)">'+pers.toLocaleString()+'</div><div style="font-size:9px;color:var(--text3)">在外人员</div></div>'+
          '<div style="padding:8px;background:var(--bg2);border-radius:8px;text-align:center"><div style="font-size:20px;font-weight:800;color:var(--green)">'+inv.toLocaleString()+'</div><div style="font-size:9px;color:var(--text3)">投资(亿$)</div></div>'+
        '</div>'+
        (ents.length?'<div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:4px">'+ents.map(function(e){return '<span class="badge b-blue" style="font-size:10px;cursor:pointer" onclick="showEntDetail('+e.id+')">'+e.short+'</span>';}).join('')+'</div>':'<div style="margin-top:6px;font-size:10px;color:var(--text3)">无在档中资企业</div>')+
        '<div style="margin-top:16px;padding-top:10px;border-top:1px solid var(--border);display:flex;gap:8px">'+
          '<button class="btn sm" style="flex:1;font-size:11px" onclick="COUNTRY_DRAWER.close();navigateTo(\'countryfile\')">📊 查看国家档案总表</button>'+
          (c?'<button class="btn sm" style="flex:1;font-size:11px" onclick="COUNTRY_DRAWER.close();showCtyDetail(\''+name+'\')">🗂️ 完整风险详情</button>':'')+
        '</div>'+
      '</div>';
    /* --- /api/cosri 增强：四维 + 项目库合并（后台静默） --- */
    fetch('/api/cosri/'+encodeURIComponent(name)).then(function(r){return r.ok?r.json():null;}).then(function(cs){
      if(!cs||cs.error||self._open!==name)return;
      /* 四维条插到指数卡下 */
      var dims=[['political','政治风险','#ff3d7f'],['economic','经济风险','#ffcc00'],['social','社会风险','#00d4ff'],['security','公共安全','#ff3355']];
      var four='<div style="margin-top:8px;display:grid;grid-template-columns:1fr 1fr;gap:6px">'+dims.map(function(kv){
        var v=cs.scores?cs.scores[kv[0]]:null;
        if(v===null||v===undefined)return '';
        return '<div style="padding:6px 8px;background:var(--bg2);border-radius:6px"><div style="display:flex;justify-content:space-between;font-size:10px"><span style="color:var(--text2)">'+kv[1]+'</span><b style="color:'+kv[2]+'">'+v+'</b></div><div style="height:4px;background:var(--bg3);border-radius:2px;margin-top:3px;overflow:hidden"><div style="width:'+(v*10)+'%;height:100%;background:'+kv[2]+'"></div></div></div>';
      }).join('')+'</div>';
      var card=d.querySelector('.cd-body');
      if(card){
        var anchor=card.children[1]; /* 指数卡 div */
        if(anchor&&anchor.insertAdjacentHTML)anchor.insertAdjacentHTML('afterend',four);
      }
      /* 项目合并：服务端项目库（interest-base 20重点项目） */
      if(cs.projects&&cs.projects.length){
        var ph=d.querySelector('#cd-projects');
        if(ph&&!localProjects.length){
          ph.innerHTML=cs.projects.slice(0,12).map(function(p){
            return '<div style="padding:7px 10px;background:var(--bg2);border-radius:6px;margin-bottom:4px;border-left:3px solid var(--cyan)">'+
              '<div style="font-size:12px;font-weight:700;color:var(--text1)">'+p.name+'</div>'+
              '<div style="font-size:10px;color:var(--text3);margin-top:2px">重点项目库 · '+(p.cat||'-')+'</div></div>';
          }).join('');
        }
      }
    }).catch(function(){});
  }
};
// ===== INTEL IMAGE CENTER (Independent View) =====
