    if((levelOrder[a.level]||0)>(levelOrder[dupFound.level]||0)) dupFound.level=a.level;
    if(a.time && (!dupFound.time || new Date(a.time)>new Date(dupFound.time))) dupFound.time=a.time;
    if(a.url && !dupFound.url) dupFound.url=a.url;
